import { useState, useEffect, useCallback, useReducer, useRef, useMemo } from 'react';
import { useNFTContractRead } from './useNFTContract';
import { useChainId } from 'wagmi';
import { G4M3_CONTRACT_CONFIG, getContractAddressByChainId } from '../contracts/contracts';
import { ethers } from 'ethers';
import { getNetworkProvider } from './usePublicProvider';

/**
 * Static manifest data for token storage
 * In production, this would be populated by a token extraction script
 */
const staticManifestData = {
  "lastUpdated": new Date().toISOString(),
  "totalTokensStored": 0,
  "version": "1.0"
};

/**
 * This hook provides functionality to load tokens with network-aware caching.
 * It implements the same functionality as react-app's staticTokenLoader.js
 * but as a React hook with chainId awareness.
 */
export function useStaticTokens() {
  const [staticTokens, setStaticTokens] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const [manifest, setManifest] = useState(staticManifestData);
  
  // Get the current chain ID
  const chainId = useChainId();
  
  // Get contract info for current network
  const contractAddress = getContractAddressByChainId(chainId);
  
  // Load total supply from contract
  const { totalSupply, isTotalSupplyLoading } = useNFTContractRead();
  
  // Create a cache key that includes the network ID
  const cacheKeyPrefix = `static-tokens-${chainId}`;
  
  /**
   * Load a static token by ID with network awareness
   */
  const loadStaticToken = useCallback(async (tokenId) => {
    if (!tokenId) return null;
    
    try {
      // Create network-specific cache key
      const tokenCacheKey = `${cacheKeyPrefix}-token-${tokenId}`;
      
      // Check localStorage first
      const cachedToken = localStorage.getItem(tokenCacheKey);
      if (cachedToken) {
        try {
          return JSON.parse(cachedToken);
        } catch (e) {
          console.warn(`Error parsing cached token #${tokenId}:`, e);
        }
      }
      
      // If the token is in our state, return it
      if (staticTokens[tokenId]) {
        return staticTokens[tokenId];
      }
      
      // If token not in cache or state, fetch from contract
      // Only do this for tokens we know exist based on totalSupply
      if (totalSupply && Number(tokenId) <= totalSupply) {
        // Fetch from contract
        try {
          const tokenURI = await fetchTokenURI(tokenId);
          if (tokenURI) {
            // Parse token URI
            const base64Data = tokenURI.split('base64,')[1];
            if (base64Data) {
              const jsonString = atob(base64Data);
              const tokenData = JSON.parse(jsonString);
              
              // Create complete token data
              const completeTokenData = {
                id: Number(tokenId),
                ...tokenData,
                source: 'contract'
              };
              
              // Cache the token
              localStorage.setItem(tokenCacheKey, JSON.stringify(completeTokenData));
              
              return completeTokenData;
            }
          }
        } catch (err) {
          console.error(`Error fetching token #${tokenId} from contract:`, err);
        }
      }
      
      console.log(`Token #${tokenId} not available for chain ${chainId}`);
      return null;
    } catch (error) {
      console.error(`Error loading static token #${tokenId}:`, error);
      return null;
    }
  }, [chainId, cacheKeyPrefix, staticTokens, totalSupply]);
  
  /**
   * Helper function to fetch token URI from contract
   * Using ethers.js v5 API
   */
  const fetchTokenURI = useCallback(async (tokenId) => {
    try {
      // Use our utility function to get a provider for this network
      const provider = getNetworkProvider(chainId);
      
      // Create contract instance with ethers v5 API
      const contract = new ethers.Contract(
        contractAddress,
        G4M3_CONTRACT_CONFIG.abi,
        provider
      );
      
      // Call the contract directly
      const uri = await contract.tokenURI(tokenId);
      return uri;
    } catch (error) {
      console.error(`Error fetching tokenURI for ${tokenId}:`, error);
      return null;
    }
  }, [contractAddress, chainId]);
  
  /**
   * Load tokens from localStorage cache or fetch them from contract
   * This implementation mirrors react-app's approach but with added network awareness
   */
  useEffect(() => {
    // Function to load tokens with network awareness
    const loadTokensForNetwork = async () => {
      setIsLoading(true);
      
      try {
        const manifestKey = `${cacheKeyPrefix}-manifest`;
        const tokensKey = `${cacheKeyPrefix}-data`;
        
        // Try to load manifest from localStorage
        const cachedManifest = localStorage.getItem(manifestKey);
        let parsedManifest = null;
        
        // Check if we have a valid manifest
        if (cachedManifest) {
          try {
            parsedManifest = JSON.parse(cachedManifest);
            setManifest(parsedManifest);
            
            // Load token data if we have a valid manifest
            const cachedTokens = localStorage.getItem(tokensKey);
            if (cachedTokens) {
              const parsedTokens = JSON.parse(cachedTokens);
              
              // Check if cache is valid
              const FIVE_MINUTES = 5 * 60 * 1000;
              const lastUpdate = new Date(parsedManifest.lastUpdated).getTime();
              const isStale = Date.now() - lastUpdate > FIVE_MINUTES;
              
              if (!isStale && parsedManifest.totalTokensStored > 0) {
                console.log(`Using ${parsedManifest.totalTokensStored} cached tokens for chain ${chainId}`);
                setStaticTokens(parsedTokens);
                setIsLoading(false);
                return;
              }
            }
          } catch (e) {
            console.warn("Error parsing cached manifest:", e);
          }
        }
        
        // At this point, we either don't have cached data, or it's stale
        // Make sure totalSupply is a number
        const totalSupplyNum = totalSupply ? Number(totalSupply) : 0;
        
        if (!totalSupplyNum || totalSupplyNum === 0) {
          console.log("No tokens to load: totalSupply is zero or undefined");
          setStaticTokens({});
          setManifest({
            ...staticManifestData,
            chainId
          });
          setIsLoading(false);
          return;
        }
        
        console.log(`Loading tokens for chain ${chainId}, totalSupply: ${totalSupplyNum}`);
        
        // Get metadata for at least the first 50 tokens (or all if less than 50)
        const MAX_TOKENS_TO_LOAD = 50;
        const tokenCount = Math.min(totalSupplyNum, MAX_TOKENS_TO_LOAD);
        const newTokens = {};
        
        // Create batches of 10 tokens at a time to avoid RPC limits
        const BATCH_SIZE = 10;
        const batches = [];
        
        for (let i = 0; i < tokenCount; i += BATCH_SIZE) {
          const batchEnd = Math.min(i + BATCH_SIZE, tokenCount);
          const tokenIds = Array.from({ length: batchEnd - i }, (_, j) => i + j + 1);
          batches.push(tokenIds);
        }
        
        // Process batches sequentially to avoid overwhelming the RPC
        for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
          const batch = batches[batchIndex];
          console.log(`Processing batch ${batchIndex + 1}/${batches.length}: tokens ${batch[0]}-${batch[batch.length - 1]}`);
          
          try {
            // Use our utility function to get a provider for this network
            const provider = getNetworkProvider(chainId);
            
            // Create contract instance
            const contract = new ethers.Contract(
              contractAddress,
              G4M3_CONTRACT_CONFIG.abi,
              provider
            );
            
            // Process each token in the batch sequentially
            for (const tokenId of batch) {
              try {
                // Fetch the token URI - in v5 we need to connect with a signer
                const uri = await contract.tokenURI(tokenId);
                
                if (uri) {
                  try {
                    // Parse base64 data - format is data:application/json;base64,<BASE64_DATA>
                    const base64Data = uri.substring(uri.indexOf('base64,') + 7);
                    if (base64Data) {
                      const jsonString = atob(base64Data);
                      const tokenData = JSON.parse(jsonString);
                      
                      // Store token data with necessary metadata
                      newTokens[tokenId] = {
                        id: tokenId,
                        uri,
                        name: tokenData.name || `Token #${tokenId}`,
                        description: tokenData.description || "",
                        image: tokenData.image || "",
                        attributes: tokenData.attributes || [],
                        chainId,
                        source: 'contract'
                      };
                    }
                  } catch (parseErr) {
                    console.error(`Error parsing token #${tokenId}:`, parseErr);
                  }
                }
              } catch (tokenErr) {
                console.error(`Error fetching token #${tokenId}:`, tokenErr);
              }
              
              // Small delay between requests to not overwhelm the RPC
              await new Promise(resolve => setTimeout(resolve, 50));
            }
            
            // Small delay between batches to avoid rate limiting
            if (batchIndex < batches.length - 1) {
              await new Promise(resolve => setTimeout(resolve, 200));
            }
          } catch (err) {
            console.error(`Error fetching batch ${batchIndex}:`, err);
          }
        }
        
        const tokenCount2 = Object.keys(newTokens).length;
        console.log(`Successfully loaded ${tokenCount2} tokens for chain ${chainId}`);
        
        // If we loaded tokens successfully, update the state and cache
        if (tokenCount2 > 0) {
          // Update manifest with metadata about what we loaded
          const newManifest = {
            lastUpdated: new Date().toISOString(),
            totalTokensStored: tokenCount2,
            minTokenId: Math.min(...Object.keys(newTokens).map(Number)),
            maxTokenId: Math.max(...Object.keys(newTokens).map(Number)),
            chainId,
            version: "1.0"
          };
          
          // Cache the results
          localStorage.setItem(manifestKey, JSON.stringify(newManifest));
          localStorage.setItem(tokensKey, JSON.stringify(newTokens));
          
          // Update state
          setManifest(newManifest);
          setStaticTokens(newTokens);
        } else {
          // If we couldn't load any tokens, use empty data
          setStaticTokens({});
          setManifest({
            ...staticManifestData,
            chainId
          });
        }
        
      } catch (err) {
        console.error('Error loading tokens:', err);
        setError(err);
      } finally {
        setIsLoading(false);
      }
    };

    loadTokensForNetwork();
  }, [chainId, cacheKeyPrefix, totalSupply, contractAddress]);

  /**
   * Load all static tokens with network awareness
   */
  const loadAllStaticTokens = useCallback(async (setLoadingCallback = null) => {
    if (setLoadingCallback) {
      setLoadingCallback(true);
    }
    
    try {
      // First check if we have cached data for this network
      const tokensKey = `${cacheKeyPrefix}-data`;
      const cachedTokens = localStorage.getItem(tokensKey);
      
      if (cachedTokens) {
        try {
          const parsedTokens = JSON.parse(cachedTokens);
          console.log(`Loaded ${Object.keys(parsedTokens).length} tokens from cache for chain ${chainId}`);
          
          if (setLoadingCallback) {
            setLoadingCallback(false);
          }
          
          return parsedTokens;
        } catch (e) {
          console.warn("Error parsing cached tokens:", e);
        }
      }
      
      // If no cache, return whatever we have in state
      return staticTokens;
      
    } catch (error) {
      console.error("Error loading all static tokens:", error);
      return {};
    } finally {
      if (setLoadingCallback) {
        setLoadingCallback(false);
      }
    }
  }, [chainId, cacheKeyPrefix, staticTokens]);

  /**
   * Get static manifest data for this network
   */
  const getStaticManifest = useCallback(() => {
    return manifest;
  }, [manifest]);

  return {
    staticTokens,
    isLoading,
    error,
    loadStaticToken,
    loadAllStaticTokens,
    getStaticManifest,
    totalSupply: totalSupply ? Number(totalSupply) : 0,
    isTotalSupplyLoading
  };
}

/**
 * Define reducer state and actions for gallery tokens
 */
const galleryInitialState = {
  status: 'idle', // 'idle', 'loading', 'success', 'error'
  allCollectibles: [],
  collectiblesByEpoch: {},
  loadProgress: 0,
  error: null,
  lastUpdated: null
};

// Reducer to manage gallery state
function galleryReducer(state, action) {
  switch (action.type) {
    case 'GALLERY_LOADING':
      return { 
        ...state, 
        status: 'loading',
        error: null
      };
    case 'GALLERY_SUCCESS':
      return {
        ...state,
        status: 'success',
        allCollectibles: action.payload.collectibles,
        collectiblesByEpoch: action.payload.byEpoch,
        loadProgress: action.payload.progress,
        lastUpdated: Date.now(),
        error: null
      };
    case 'GALLERY_ERROR':
      return { 
        ...state, 
        status: 'error', 
        error: action.payload 
      };
    case 'GALLERY_RESET':
      return galleryInitialState;
    default:
      return state;
  }
}

/**
 * Hook for loading and managing gallery tokens
 * This version uses reducer pattern for better state management and network switching
 */
export function useNFTGallery() {
  // Use reducer instead of multiple state variables
  const [state, dispatch] = useReducer(galleryReducer, galleryInitialState);
  
  // Track if component is mounted
  const isMounted = useRef(true);
  
  // Use the chain-aware static tokens hook
  const { 
    staticTokens, 
    isLoading: isLoadingStaticTokens, 
    totalSupply, 
    isTotalSupplyLoading,
    error: staticTokensError
  } = useStaticTokens();
  
  // Get current chain ID for network-aware caching
  const chainId = useChainId();
  
  // Create a cache key that includes the network ID
  const cacheKey = useMemo(() => 
    `gallery-tokens-${chainId}`,
    [chainId]
  );
  
  // Helper function to extract epoch from a token
  const getTokenEpoch = useCallback((token) => {
    if (!token.attributes) return 'unknown';
    
    const epochAttr = token.attributes.find(attr => 
      attr.trait_type && attr.trait_type.toLowerCase() === 'epoch'
    );
    
    if (epochAttr && epochAttr.value) {
      // Clean up the epoch value (remove # if present and convert to string)
      return epochAttr.value.toString().replace('#', '');
    }
    
    // If no epoch attribute, check if it's in the name
    if (token.name) {
      const epochMatch = token.name.match(/(\d+)\/\d+/);
      if (epochMatch) {
        return epochMatch[1];
      }
    }
    
    return 'unknown';
  }, []);
  
  // Helper function to extract generation from a token
  const getTokenGeneration = useCallback((token) => {
    if (!token.attributes) return 0;
    
    const genAttr = token.attributes.find(attr => 
      attr.trait_type && attr.trait_type.toLowerCase() === 'generation'
    );
    
    if (genAttr && genAttr.value) {
      // Clean up the generation value (remove # if present and convert to number)
      return parseInt(genAttr.value.toString().replace('#', ''), 10) || 0;
    }
    
    return 0;
  }, []);
  
  // Process and organize tokens by epoch
  const organizeTokensByEpoch = useCallback((tokenArray) => {
    // Group by epoch
    const byEpoch = {};
    
    // Process and group tokens by epoch
    tokenArray.forEach(token => {
      const epoch = getTokenEpoch(token);
      
      if (!byEpoch[epoch]) {
        byEpoch[epoch] = [];
      }
      
      byEpoch[epoch].push(token);
    });
    
    // Sort tokens within each epoch by generation and then by ID
    Object.keys(byEpoch).forEach(epoch => {
      byEpoch[epoch].sort((a, b) => {
        const genA = getTokenGeneration(a);
        const genB = getTokenGeneration(b);
        
        // First sort by generation
        if (genA !== genB) {
          return genA - genB;
        }
        
        // If same generation, sort by token ID
        return (a.id || 0) - (b.id || 0);
      });
    });
    
    return byEpoch;
  }, [getTokenEpoch, getTokenGeneration]);
  
  // Function to process tokens and update gallery state
  const processAndUpdateGallery = useCallback(() => {
    // Skip if still loading static tokens
    if (isLoadingStaticTokens) return;
    
    // Start loading
    dispatch({ type: 'GALLERY_LOADING' });
    
    try {
      // Check cache first for efficiency
      const cachedGallery = localStorage.getItem(cacheKey);
      if (cachedGallery) {
        try {
          const { collectibles, byEpoch, progress, timestamp, cachedChainId } = JSON.parse(cachedGallery);
          
          // Check if cache is for the current network and is fresh (less than 5 minutes old)
          const FIVE_MINUTES = 5 * 60 * 1000;
          const isFresh = (Date.now() - timestamp) < FIVE_MINUTES;
          const isCorrectNetwork = cachedChainId === chainId;
          
          // If cache is fresh, for the current network, and we have collectibles, use them
          if (isFresh && isCorrectNetwork && collectibles && collectibles.length > 0) {
            console.log(`Using ${collectibles.length} cached gallery collectibles for chain ${chainId}`);
            
            if (isMounted.current) {
              dispatch({
                type: 'GALLERY_SUCCESS',
                payload: {
                  collectibles,
                  byEpoch,
                  progress
                }
              });
            }
            return;
          }
        } catch (err) {
          console.warn("Error parsing cached gallery:", err);
        }
      }
      
      console.log(`Building gallery from ${Object.keys(staticTokens).length} tokens for chain ${chainId}`);
      
      // Convert the staticTokens object to an array and add chainId
      const tokenArray = Object.values(staticTokens).map(token => ({
        ...token,
        chainId // Ensure chain ID is included
      }));
      
      // Group and organize by epoch
      const byEpoch = organizeTokensByEpoch(tokenArray);
      
      // Calculate load progress based on what we've loaded compared to total supply
      const progress = totalSupply ? 
        Math.min(100, (tokenArray.length * 100) / totalSupply) : 
        (tokenArray.length > 0 ? 100 : 0);
      
      // Debug log the tokens by epoch
      Object.keys(byEpoch).forEach(epoch => {
        console.log(`Epoch ${epoch}: ${byEpoch[epoch].length} tokens`);
      });
      
      // Cache the results for future use - include chainId in cache data
      const galleryCache = {
        collectibles: tokenArray,
        byEpoch,
        progress,
        timestamp: Date.now(),
        cachedChainId: chainId // Store the network this cache is for
      };
      
      try {
        localStorage.setItem(cacheKey, JSON.stringify(galleryCache));
      } catch (cacheErr) {
        console.warn("Error caching gallery data:", cacheErr);
      }
      
      // Update state
      if (isMounted.current) {
        dispatch({
          type: 'GALLERY_SUCCESS',
          payload: {
            collectibles: tokenArray,
            byEpoch,
            progress
          }
        });
      }
    } catch (err) {
      console.error('Error loading gallery:', err);
      if (isMounted.current) {
        dispatch({ type: 'GALLERY_ERROR', payload: err.message });
      }
    }
  }, [
    staticTokens, 
    isLoadingStaticTokens, 
    cacheKey, 
    totalSupply, 
    chainId, 
    organizeTokensByEpoch
  ]);
  
  // Process when static tokens data changes or network changes
  useEffect(() => {
    // Set mounted flag
    isMounted.current = true;
    
    // Reset state when chain changes
    if (chainId) {
      // Process tokens when static tokens are loaded
      processAndUpdateGallery();
    }
    
    // Cleanup
    return () => {
      isMounted.current = false;
    };
  }, [chainId, staticTokens, processAndUpdateGallery]);
  
  // Create a stable return value
  return useMemo(() => ({
    allCollectibles: state.allCollectibles,
    collectiblesByEpoch: state.collectiblesByEpoch,
    isLoadingGallery: state.status === 'loading' || isLoadingStaticTokens || isTotalSupplyLoading,
    loadProgress: state.loadProgress,
    error: state.error || staticTokensError,
    // Helper methods that might be useful in components
    getTokenEpoch,
    getTokenGeneration,
    // Force refresh method
    refreshGallery: () => {
      localStorage.removeItem(cacheKey);
      processAndUpdateGallery();
    }
  }), [
    state, 
    isLoadingStaticTokens, 
    isTotalSupplyLoading, 
    staticTokensError,
    getTokenEpoch,
    getTokenGeneration,
    cacheKey,
    processAndUpdateGallery
  ]);
}