import { useMemo } from 'react';
import { createPublicClient, http } from 'viem';
import { mainnet, polygonAmoy } from 'wagmi/chains';
import { ALCHEMY_KEY, getTargetNetwork } from '../constants';
import { ethers } from 'ethers';
import { useChainId } from 'wagmi';

// Create a stable object to hold client references
// Using a React ref pattern outside of component to maintain stability
const CLIENT_CACHE = {};

// Pre-create clients for known networks to avoid creation during render
const getOrCreateClient = (chainId) => {
  // If we already have a cached client, return it
  if (CLIENT_CACHE[chainId]) {
    return CLIENT_CACHE[chainId];
  }
  
  console.log(`Creating new public client for chain ID: ${chainId}`);
  
  // Select appropriate chain and RPC URL based on the chain
  let chain = mainnet;
  let rpcUrl = `https://eth-mainnet.g.alchemy.com/v2/${ALCHEMY_KEY}`;
  
  // Use chain-specific configs
  if (chainId === 80002) {
    chain = polygonAmoy;
    // Use a CORS-friendly endpoint
    rpcUrl = 'https://polygon-amoy.public.blastapi.io';
  }
  
  // Create and store the client in our cache
  const publicClient = createPublicClient({
    chain,
    transport: http(rpcUrl, {
      batch: { batchSize: 1 },
      fetchOptions: {
        mode: 'cors',
        cache: 'no-cache',
      },
      timeout: 30000,
    }),
  });
  
  // Cache the client for this chainId
  CLIENT_CACHE[chainId] = publicClient;
  
  return publicClient;
};

/**
 * Creates a public provider for read-only access when no wallet is available
 */
export function usePublicProvider() {
  const chainId = useChainId();
  
  // Use ref pattern to ensure stable reference across renders
  const clientRef = useMemo(() => {
    // Get or create a client for this chainId
    return getOrCreateClient(chainId);
  }, [chainId]); // Only depend on chainId to support network switching
  
  return clientRef;
}

/**
 * Hook to detect if a wallet is available or if we're in read-only mode
 */
export function useWalletStatus() {
  // Check if MetaMask or other wallets are available
  const isWalletAvailable = useMemo(() => {
    if (typeof window === 'undefined') return false;
    return Boolean(window.ethereum || window.web3);
  }, []);
  
  return {
    isWalletAvailable,
    isReadOnly: !isWalletAvailable
  };
}

/**
 * Utility function to get an ethers provider for a specific network
 * This can be used outside of React components - uses ethers.js v5 API
 */
export const getNetworkProvider = (chainId) => {
  try {
    if (window.ethereum) {
      // Use Web3Provider in ethers v5 (equivalent to BrowserProvider in v6)
      return new ethers.providers.Web3Provider(window.ethereum);
    } else {
      // Fallback to network-specific RPC URLs
      switch (chainId) {
        case 1: // Ethereum Mainnet
          return new ethers.providers.JsonRpcProvider('https://eth-mainnet.public.blastapi.io');
        case 80002: // Polygon Amoy testnet
          // Use a CORS-friendly RPC endpoint for Amoy
          return new ethers.providers.JsonRpcProvider('https://polygon-amoy.public.blastapi.io');
        case 31337: // Localhost
          return new ethers.providers.JsonRpcProvider('http://localhost:8545');
        default:
          return ethers.getDefaultProvider();
      }
    }
  } catch (error) {
    console.error("Error creating provider:", error);
    // Default fallback
    return new ethers.providers.JsonRpcProvider('https://eth-mainnet.public.blastapi.io');
  }
};