// Network-specific contract addresses
const addresses = {
  // For localhost, we use an empty string - this allows the frontend to use 
  // whatever address is in the artifacts
  localhost: "0x5FC8d32690cc91D4c39d9d3abcBD16989F875707",
  
  // Polygon Amoy testnet address
  amoy: "0x149D4C0578A04c3A1D3c5cB9821EFC5bfe25E965",
  
  // Ethereum Mainnet address
  mainnet: "0xc5D80066AF7F75D568413B1778fD52d91642aDe3" // Deployed on Ethereum mainnet
};

// Detect which network we're on
export const getNetworkType = () => {
  // Check if we're in a browser environment
  if (typeof window === 'undefined') return 'localhost';
  
  // First check environment variables (most reliable method)
  if (process.env.REACT_APP_TARGET_NETWORK === 'mainnet' || 
      process.env.REACT_APP_NETWORK === 'mainnet') {
    console.log("Using mainnet from environment variables");
    return 'mainnet';
  }
  
  // GitHub Pages deployment
  if (window.location.hostname.includes('github.io') || window.location.protocol === 'https:') {
    // For production site, we'll use mainnet by default
    console.log("Using mainnet for GitHub Pages deployment");
    return 'mainnet';
  }
  
  // Default to localhost for local development
  console.log("Using localhost network");
  return 'localhost';
};

// Create a function to get the contract address based on chain ID
export const getContractAddressByChainId = (chainId) => {
  if (!chainId) return addresses.mainnet; // Default to mainnet if no chainId provided
  
  switch(chainId) {
    case 31337: // localhost
      return addresses.localhost;
    case 80002: // Polygon Amoy
      return addresses.amoy;
    case 1: // Ethereum Mainnet
      return addresses.mainnet;
    default:
      console.warn(`No contract address configured for chainId ${chainId}, using mainnet address as fallback`);
      return addresses.mainnet;
  }
};

// For initial setup, use the network from the getNetworkType function
const networkType = getNetworkType();
console.log("Initial contract network:", networkType);

// Get the initial contract address based on the network
export const G4M3_ADDRESS = addresses[networkType] || addresses.mainnet;

// Export contract config for wagmi hooks
export const G4M3_CONTRACT_CONFIG = {
  address: G4M3_ADDRESS,
  abi: G4M3_ABI,
};