import React, { useState, useEffect, useRef } from 'react';
import { Typography, Row, Col, Progress } from 'antd';
import { PlayCircleOutlined, ReloadOutlined } from '@ant-design/icons';
import { useNFTGallery } from '../../hooks';
import { useChainId } from 'wagmi';
import { styles } from './styles';
import Win311Loading from '../ui/Win311Loading';
import ItemCard from '../ui/ItemCard';
import AnimationModal from '../ui/AnimationModal';

const { Title } = Typography;

// Component to display gallery stats and debug info
const GalleryStats = ({ allCollectibles, collectiblesByEpoch, totalSupply }) => {
  return (
    <div
      style={{
        background: "#222",
        color: "#aaa",
        fontFamily: "monospace",
        fontSize: "12px",
        padding: "12px",
        marginBottom: "16px",
        borderRadius: "4px",
      }}
    >
      <div
        style={{
          marginBottom: "8px",
          borderBottom: "1px solid #444",
          paddingBottom: "4px",
          color: "#fff",
          fontWeight: "bold",
        }}
      >
        Gallery Stats
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: "16px" }}>
        <div>
          <span style={{ color: "#00d0ff" }}>Tokens available:</span> {allCollectibles?.length || 0}
        </div>
        <div>
          <span style={{ color: "#00d0ff" }}>Epochs found:</span> {Object.keys(collectiblesByEpoch).length}
        </div>
        <div>
          <span style={{ color: "#00d0ff" }}>Total minted:</span> {totalSupply || "Loading..."}
        </div>
      </div>
      <div style={{ marginTop: "8px", display: "flex", flexWrap: "wrap" }}>
        {Object.entries(collectiblesByEpoch)
          .sort(([a], [b]) => parseInt(a) - parseInt(b))
          .map(([epoch, tokens]) => (
            <div
              key={epoch}
              style={{
                margin: "4px",
                padding: "4px 8px",
                background: "#333",
                borderRadius: "4px",
                border: "1px solid #555",
              }}
            >
              <span style={{ color: "#ffcc00" }}>Epoch {epoch}:</span> {tokens.length} tokens
            </div>
          ))}
      </div>
    </div>
  );
};

// Gallery controls component - removed refresh button as requested
const GalleryControls = () => {
  return null; // No controls displayed
};

const GallerySection = () => {
  const { 
    allCollectibles, 
    collectiblesByEpoch, 
    isLoadingGallery, 
    loadProgress,
    totalSupply,
    refreshGallery // Add the refreshGallery function
  } = useNFTGallery();
  
  // For debugging purposes
  console.log("Gallery loaded tokens:", {
    allCollectiblesCount: allCollectibles?.length,
    epochCount: Object.keys(collectiblesByEpoch || {}).length,
    totalSupply,
    isLoading: isLoadingGallery,
    progress: loadProgress
  });
  
  const [animationModalVisible, setAnimationModalVisible] = useState(false);
  const [selectedEpoch, setSelectedEpoch] = useState(null);
  const [refreshing, setRefreshing] = useState(false);
  
  // Get current chain ID for network display
  const chainId = useChainId();
  
  // Use ref to track previous chainId for comparison
  const previousChainIdRef = useRef(chainId);
  
  // Fixed size for items (using the middle size from previous implementation)
  const ITEM_SIZE = 150;
  
  // Handle opening animation modal
  const handleOpenAnimation = (epoch) => {
    setSelectedEpoch(epoch);
    setAnimationModalVisible(true);
  };
  
  // Watch for actual network changes and safely refresh gallery
  useEffect(() => {
    // Only refresh if chainId has actually changed from a previous value (and not initial render)
    if (previousChainIdRef.current !== undefined && previousChainIdRef.current !== chainId) {
      console.log(`Network changed from ${previousChainIdRef.current} to ${chainId}, forcing complete gallery refresh`);
      
      // Safety mechanism: clear ALL relevant caches to ensure a clean slate
      const staticTokensCacheKey = `static-tokens-${chainId}`;
      const galleryCacheKey = `gallery-tokens-${chainId}`;
      const oldStaticCacheKey = `static-tokens-${previousChainIdRef.current}`;
      const oldGalleryCacheKey = `gallery-tokens-${previousChainIdRef.current}`;
      
      // Clear all caches to force complete reload
      localStorage.removeItem(staticTokensCacheKey + '-manifest');
      localStorage.removeItem(staticTokensCacheKey + '-data');
      localStorage.removeItem(galleryCacheKey);
      localStorage.removeItem(oldStaticCacheKey + '-manifest');
      localStorage.removeItem(oldStaticCacheKey + '-data');
      localStorage.removeItem(oldGalleryCacheKey);
      
      // Force timeout to ensure effect doesn't run too frequently
      const timeoutId = setTimeout(() => {
        // Set refreshing indicator
        setRefreshing(true);
        
        // Use the built-in refresh function if available
        if (refreshGallery) {
          refreshGallery();
          
          // Reset refreshing state after a short delay
          setTimeout(() => {
            setRefreshing(false);
          }, 1000);
        }
      }, 100);
      
      // Update ref to current chainId after refresh is scheduled
      previousChainIdRef.current = chainId;
      
      // Cleanup timeout to prevent memory leaks
      return () => {
        clearTimeout(timeoutId);
      };
    } else if (previousChainIdRef.current === undefined) {
      // Initialize the ref on first render without triggering refresh
      previousChainIdRef.current = chainId;
    }
  }, [chainId, refreshGallery]);
  
  // Handle manual refresh - update to use the refreshGallery function
  const handleRefresh = () => {
    setRefreshing(true);
    
    // Use the refreshGallery function from the hook instead of manually clearing cache
    // This will properly handle the refresh without page reload
    if (refreshGallery) {
      refreshGallery();
      
      // Reset refreshing state after a short delay
      setTimeout(() => {
        setRefreshing(false);
      }, 500);
    } else {
      // Fallback to old method if refreshGallery isn't available
      // Clear caches for both static tokens and gallery
      const staticCacheKey = `static-tokens-${chainId}`;
      const galleryCacheKey = `gallery-tokens-${chainId}`;
      localStorage.removeItem(staticCacheKey + '-manifest');
      localStorage.removeItem(staticCacheKey + '-data');
      localStorage.removeItem(galleryCacheKey);
      
      // Reset refreshing state after a short delay
      setTimeout(() => {
        setRefreshing(false);
        // Reload to apply changes
        window.location.reload();
      }, 500);
    }
  };
  
  // Network info removed as requested
  
  // Debug mode to show gallery stats
  const [showStats, setShowStats] = useState(false);
  
  // Toggle stats when pressing S key
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key.toLowerCase() === 's') {
        setShowStats(prev => !prev);
      }
    };
    
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);
  
  return (
    <div style={{ ...styles.section, background: "#111", paddingBottom: "80px" }}>
      <div style={styles.container}>
        <div style={{ display: "flex", justifyContent: "center", alignItems: "center", marginBottom: "20px" }}>
          <Title level={2} style={styles.sectionTitle}>
            Gallery
          </Title>
        </div>
        
        {/* Controls row removed as requested */}
        
        {/* Optional stats display - press 'S' to toggle */}
        {showStats && (
          <GalleryStats 
            allCollectibles={allCollectibles} 
            collectiblesByEpoch={collectiblesByEpoch}
            totalSupply={totalSupply}
          />
        )}
        
        {/* Gallery with loading overlay */}
        <div style={{ position: "relative" }}>
          {/* Loading overlay */}
          {isLoadingGallery && (
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                zIndex: 100,
                background: "rgba(0,0,0,0.8)",
                padding: "16px",
                borderRadius: "4px",
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: "16px",
              }}
            >
              <Win311Loading />
              <div style={{ fontFamily: "'PixelOperator', monospace", marginTop: "8px", color: "#fff" }}>
                Loading more tokens...
              </div>
              <Progress percent={Math.round(loadProgress)} status="active" style={{ width: "80%" }} />
              <div style={{ fontFamily: "'PixelOperator', monospace", fontSize: "12px", color: "#aaa" }}>
                Displaying {allCollectibles.length} tokens so far
              </div>
            </div>
          )}
          
          {/* Gallery content */}
          {Object.keys(collectiblesByEpoch).length > 0 ? (
            <div
              style={{
                overflow: "auto",
                height: "calc(70vh)",
                maxHeight: "800px",
                width: "100%",
                margin: "16px 0",
                padding: "12px",
                opacity: isLoadingGallery ? 0.6 : 1,
                transition: "opacity 0.3s ease",
                background: "#0e0e0e", // Keep dark background to make epochs stand out
                border: "8px solid #404040", // Add dark gray frame
                borderRadius: "4px",
                boxSizing: "border-box",
              }}
            >
              <div
                style={{
                  display: "flex",
                  flexDirection: "row",
                  gap: "4px", // Reduced gap for snugger fit
                  minHeight: "100%",
                  minWidth: Object.keys(collectiblesByEpoch).length * (ITEM_SIZE + 8), // Using fixed size
                }}
              >
                {/* Create a column for each epoch */}
                {Object.keys(collectiblesByEpoch)
                  .sort((a, b) => Number(a) - Number(b))
                  .map(epoch => (
                    <div 
                      key={`epoch-${epoch}`} 
                      style={{
                        display: "flex",
                        flexDirection: "column",
                        width: ITEM_SIZE,
                        gap: "4px", // Reduced gap for snugger fit
                        alignItems: "center",
                      }}
                    >
                      <h3
                        style={{
                          fontFamily: "'PixelOperator', monospace",
                          color: "#FFFFFF",
                          position: "sticky",
                          top: 0,
                          background: "#000080", // Windows 3.11 title bar blue
                          width: "100%",
                          padding: "4px 0",
                          marginTop: 0,
                          marginBottom: "8px",
                          fontSize: "14px",
                          textAlign: "center",
                          zIndex: 10,
                          position: "relative", // For positioning play button
                          border: "1px solid",
                          borderTop: "1px solid #FFFFFF",
                          borderLeft: "1px solid #FFFFFF",
                          borderBottom: "1px solid #000000",
                          borderRight: "1px solid #404040",
                        }}
                      >
                        Epoch {epoch}
                        <button
                          onClick={(e) => {
                            e.stopPropagation(); // Prevent event bubbling
                            
                            // Get the button element
                            const button = e.currentTarget;
                            
                            // Add pressed styling
                            button.style.borderColor = "#404040 #FFFFFF #FFFFFF #404040";
                            button.style.transform = "translateY(1px)";
                            button.style.boxShadow = "0px 0px 0 #000000";
                            
                            // Reset to normal after short delay
                            setTimeout(() => {
                              if (button) {
                                button.style.borderColor = "#FFFFFF #404040 #404040 #FFFFFF";
                                button.style.transform = "translateY(0)";
                                button.style.boxShadow = "1px 1px 0 #000000";
                              }
                              
                              // Open animation modal
                              handleOpenAnimation(epoch);
                            }, 100);
                          }}
                          style={{
                            position: "absolute",
                            right: 5,
                            top: 2,
                            width: "20px",
                            height: "20px",
                            background: "#C0C0C0",
                            color: "#000000",
                            border: "2px solid",
                            borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                            boxShadow: "1px 1px 0 #000000",
                            padding: 0,
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            cursor: "pointer",
                            fontSize: "10px",
                            transition: "transform 0.05s, box-shadow 0.05s, border-color 0.05s",
                          }}
                        >
                          <PlayCircleOutlined style={{ fontSize: '10px' }} />
                        </button>
                      </h3>
                      
                      <div
                        style={{
                          display: "flex",
                          flexDirection: "column",
                          gap: "4px", // Reduced gap for snugger fit
                          alignItems: "center",
                          width: "100%",
                        }}
                      >
                        {collectiblesByEpoch[epoch].map(item => (
                          <div 
                            key={`token-${item.id}`} 
                            style={{ 
                              width: ITEM_SIZE,
                              height: ITEM_SIZE,
                            }}
                          >
                            <ItemCard 
                              item={item} 
                              size="gallery"
                            />
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
              </div>
            </div>
          ) : !isLoadingGallery ? (
            // No tokens and not loading
            <div style={{ 
              textAlign: "center", 
              padding: "40px 0",
              background: "#0e0e0e",
              border: "8px solid #404040",
              borderRadius: "4px",
              marginTop: "16px",
              boxSizing: "border-box"
            }}>
              <div style={{ 
                fontFamily: "'PixelOperator', monospace", 
                fontSize: "16px", 
                color: "#fff", 
                marginBottom: "20px" 
              }}>
                No tokens found in the gallery.
              </div>
              <button
                style={{
                  margin: "15px auto",
                  padding: "2px 8px",
                  height: "28px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  minWidth: "100px",
                  fontFamily: "'PixelOperator', monospace",
                  fontWeight: "bold",
                  background: "#C0C0C0",
                  color: "#000000",
                  border: "2px solid",
                  borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                  boxShadow: "1px 1px 0 #000000",
                  cursor: "pointer",
                  transition: "transform 0.05s, box-shadow 0.05s, border-color 0.05s",
                }}
                onClick={handleRefresh}
                disabled={refreshing}
                onMouseDown={(e) => {
                  e.currentTarget.style.borderColor = "#404040 #FFFFFF #FFFFFF #404040";
                  e.currentTarget.style.transform = "translateY(1px)";
                  e.currentTarget.style.boxShadow = "0px 0px 0 #000000";
                }}
                onMouseUp={(e) => {
                  e.currentTarget.style.borderColor = "#FFFFFF #404040 #404040 #FFFFFF";
                  e.currentTarget.style.transform = "translateY(0)";
                  e.currentTarget.style.boxShadow = "1px 1px 0 #000000";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.borderColor = "#FFFFFF #404040 #404040 #FFFFFF";
                  e.currentTarget.style.transform = "translateY(0)";
                  e.currentTarget.style.boxShadow = "1px 1px 0 #000000";
                }}
              >
                <ReloadOutlined spin={refreshing} style={{ marginRight: "6px" }} />
                <u>R</u>efresh
              </button>
            </div>
          ) : null}
        </div>
        
        {/* Animation Modal */}
        <AnimationModal
          visible={animationModalVisible}
          onClose={() => setAnimationModalVisible(false)}
          initialEpoch={selectedEpoch}
          tokens={selectedEpoch && collectiblesByEpoch[selectedEpoch] 
            ? [...collectiblesByEpoch[selectedEpoch]] // Create a new array to avoid reference issues 
            : []}
        />
      </div>
    </div>
  );
};

export default GallerySection;