import { RainbowKitProvider as RKProvider, getDefaultWallets, darkTheme, lightTheme, midnightTheme } from '@rainbow-me/rainbowkit';
import { http, fallback } from 'wagmi';
import { createConfig, WagmiConfig } from 'wagmi';
import { mainnet, localhost } from 'wagmi/chains';
import { ALCHEMY_KEY, WALLET_CONNECT_PROJECT_ID, getTargetNetwork } from '../constants';
import '@rainbow-me/rainbowkit/styles.css';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { useEffect } from 'react';

// Define our amoy testnet
const amoy = {
  id: 80002,
  name: 'Polygon Amoy',
  network: 'amoy',
  nativeCurrency: {
    decimals: 18,
    name: 'Matic',
    symbol: 'MATIC',
  },
  rpcUrls: {
    public: { http: [`https://polygon-amoy.g.alchemy.com/v2/${ALCHEMY_KEY}`] },
    default: { http: [`https://polygon-amoy.g.alchemy.com/v2/${ALCHEMY_KEY}`] },
  },
  blockExplorers: {
    etherscan: { name: 'OKLink', url: 'https://www.oklink.com/amoy' },
    default: { name: 'OKLink', url: 'https://www.oklink.com/amoy' },
  },
  testnet: true,
};

// Create a new query client instance
const queryClient = new QueryClient();

const RainbowKitProvider = ({ children }) => {
  const targetNetwork = getTargetNetwork();
  
  const chains = [mainnet, localhost, amoy];
  
  // Set up connectors
  const { connectors } = getDefaultWallets({
    appName: 'g4m3 0f l1f3',
    projectId: WALLET_CONNECT_PROJECT_ID,
    chains,
    walletConnectOptions: {
      // Configure options to make WalletConnect more robust
      projectId: WALLET_CONNECT_PROJECT_ID,
      showQrModal: true,
      optionalChains: [mainnet.id, localhost.id, amoy.id],
      metadata: {
        name: 'g4m3 0f l1f3',
        description: 'Loogies SVG NFT',
        url: window.location.href,
        icons: [`${window.location.origin}/logo192.png`]
      }
    }
  });
  
  // Create wagmi config with more robust configuration and fallbacks
  const wagmiConfig = createConfig({
    chains,
    connectors,
    transports: {
      [mainnet.id]: fallback([
        http(`https://eth-mainnet.g.alchemy.com/v2/${ALCHEMY_KEY}`, {
          batch: { batchSize: 1 }, // Reduce batch size for more reliable responses
          fetchOptions: {
            mode: 'cors',
            cache: 'no-cache',
          },
          timeout: 30000, // Increase timeout
        }),
        http('https://eth.llamarpc.com'), // Adding LlamaRPC as a fallback
        http('https://ethereum.publicnode.com'), // Adding PublicNode as a fallback
      ]),
      [localhost.id]: http('http://localhost:8545', {
        timeout: 30000,
      }),
      [amoy.id]: fallback([
        http(`https://polygon-amoy.g.alchemy.com/v2/${ALCHEMY_KEY}`, {
          batch: { batchSize: 1 },
          fetchOptions: {
            mode: 'cors',
            cache: 'no-cache',
          },
          timeout: 30000,
        }),
        http('https://polygon-amoy-rpc.publicnode.com'), // Public node fallback
      ]),
    },
    syncConnectedChain: true,
    logger: {
      warn: (message) => console.warn(message),
      error: (message) => {
        console.error("Wallet connection error:", message);
        // You could trigger a UI notification here if needed
      },
    },
  });
  
  return (
    <QueryClientProvider client={queryClient}>
      <WagmiConfig config={wagmiConfig}>
        <RKProvider 
          chains={chains}
          theme={darkTheme({
            accentColor: '#c0c0c0', // Windows-like silver
            accentColorForeground: '#000000',
            borderRadius: 'small',
            fontStack: 'system',
            overlayBlur: 'small',
          })}
          modalSize="compact"
        >
          {children}
        </RKProvider>
      </WagmiConfig>
    </QueryClientProvider>
  );
};

export default RainbowKitProvider;