import React, { useState, useCallback, useMemo } from "react";
import { Row, Col, Typography, Button, Card } from "antd";
import { useAccount, useChainId } from "wagmi";
import { ReloadOutlined } from "@ant-design/icons";
import { useNFTCollection } from "../../hooks";
import { styles } from "./styles";
import Win311Loading from "../ui/Win311Loading";
import ItemCard from "../ui/ItemCard";

const { Title } = Typography;

// Network specific info - moved outside component
const getNetworkName = (chainId) => {
  switch (chainId) {
    case 1:
      return "Ethereum Mainnet";
    case 80002:
      return "Polygon Amoy Testnet";
    case 31337:
      return "Localhost";
    default:
      return `Chain ID: ${chainId}`;
  }
};

const MyItemsSection = () => {
  const { address, isConnected } = useAccount();
  const {
    yourCollectibles,
    collectiblesByEpoch,
    isLoading: isLoadingCollection,
    detectedCollectibles,
    balance,
  } = useNFTCollection();

  const [refreshing, setRefreshing] = useState(false);

  // Get current chain ID for network display and cache management
  const chainId = useChainId();

  // Create a stable cache key reference
  const cacheKey = useMemo(
    () => `collectibles-${chainId}-${address || "none"}`,
    [chainId, address]
  );

  // Handle manual refresh
  const handleRefresh = useCallback(() => {
    setRefreshing(true);

    // Clear cache for this user's collectibles
    localStorage.removeItem(cacheKey);

    // Use a more targeted refresh approach rather than full page reload
    setTimeout(() => {
      setRefreshing(false);
    }, 500);
  }, [cacheKey]);

  // Render loading state
  const renderLoadingState = useCallback(
    () => (
      <Col
        span={24}
        style={{
          textAlign: "center",
          paddingTop: "20px",
          paddingBottom: "20px",
        }}
      >
        <Win311Loading />
        <div
          style={{
            marginTop: "20px",
            fontFamily: "'PixelOperator', monospace",
            padding: "10px",
            display: "inline-block",
            color: "#FFFFFF",
          }}
        >
          Loading your collection...
          {detectedCollectibles > 0 && (
            <div style={{ marginTop: "10px", fontSize: "14px", color: "#CCCCCC" }}>
              Found {detectedCollectibles} tokens so far
            </div>
          )}
        </div>
      </Col>
    ),
    [detectedCollectibles]
  );

  // Render not connected state
  const renderNotConnectedState = useCallback(
    () => (
      <Col
        span={24}
        style={{
          textAlign: "center",
          paddingTop: "20px",
          paddingBottom: "20px",
        }}
      >
        <div
          style={{
            fontFamily: "'PixelOperator', monospace",
            fontSize: "16px",
            padding: "20px",
            color: "#FFFFFF",
            maxWidth: "400px",
            margin: "0 auto",
          }}
        >
          Connect your wallet to view your collection.
        </div>
      </Col>
    ),
    []
  );

  // Render empty state
  const renderEmptyState = useCallback(
    () => (
      <Col
        span={24}
        style={{ textAlign: "center", paddingTop: "0", paddingBottom: "10px" }}
      >
        <div
          style={{
            fontFamily: "'PixelOperator', monospace",
            fontSize: "16px",
            marginBottom: "0",
            padding: "0",
            maxWidth: "500px",
            margin: "0 auto",
          }}
        >
          <div style={{ marginBottom: "15px", color: "#FFFFFF" }}>
            You don't have any tokens yet.
          </div>
          <button
            style={{
              fontSize: "11pt",
              padding: "2px 8px",
              height: "28px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              minWidth: "100px",
              fontFamily: "'PixelOperator', monospace",
              fontWeight: "bold",
              background: "#C0C0C0",
              color: "#000000",
              border: "2px solid",
              borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
              boxShadow: "1px 1px 0 #000000",
              cursor: "pointer",
              transition:
                "transform 0.05s, box-shadow 0.05s, border-color 0.05s",
              margin: "0 auto",
            }}
            onClick={handleRefresh}
            disabled={refreshing}
            onMouseDown={(e) => {
              e.currentTarget.style.borderColor =
                "#404040 #FFFFFF #FFFFFF #404040";
              e.currentTarget.style.transform = "translateY(1px)";
              e.currentTarget.style.boxShadow = "0px 0px 0 #000000";
            }}
            onMouseUp={(e) => {
              e.currentTarget.style.borderColor =
                "#FFFFFF #404040 #404040 #FFFFFF";
              e.currentTarget.style.transform = "translateY(0)";
              e.currentTarget.style.boxShadow = "1px 1px 0 #000000";
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.borderColor =
                "#FFFFFF #404040 #404040 #FFFFFF";
              e.currentTarget.style.transform = "translateY(0)";
              e.currentTarget.style.boxShadow = "1px 1px 0 #000000";
            }}
          >
            <ReloadOutlined spin={refreshing} style={{ marginRight: "6px" }} />
            <u>R</u>efresh
          </button>
        </div>
      </Col>
    ),
    [chainId, handleRefresh, refreshing]
  );

  // Render all tokens in a single view
  const renderTokensView = useCallback(
    () => (
      <Col span={24}>
        <Row gutter={[16, 16]}>
          {yourCollectibles.map((item, index) => (
            <Col
              xs={24}
              sm={12}
              md={8}
              lg={6}
              key={`token-${item.id || index}`}
            >
              <ItemCard item={item} />
            </Col>
          ))}
        </Row>
      </Col>
    ),
    [yourCollectibles]
  );

  // Create stable content element using the single view
  const content = useMemo(() => {
    if (!isConnected) {
      return renderNotConnectedState();
    }

    // Check if balance is known (not undefined) and is zero
    // This means we know the user has no tokens, so we can show empty state
    // instead of a loading indicator
    if (balance !== undefined && balance === 0) {
      return renderEmptyState();
    }

    if (isLoadingCollection) {
      return renderLoadingState();
    }

    if (yourCollectibles && yourCollectibles.length > 0) {
      // Show all tokens in a single view
      return renderTokensView();
    }

    // No collectibles
    return renderEmptyState();
  }, [
    isLoadingCollection,
    isConnected,
    balance,
    yourCollectibles,
    renderLoadingState,
    renderNotConnectedState,
    renderTokensView,
    renderEmptyState,
  ]);

  // Network info removed as requested

  return (
    <div style={{
      background: "#404040",
      width: "100%",
      paddingTop: "60px",
      paddingBottom: "60px",
    }}>
      <div style={styles.container}>
        <div
          style={{
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            marginBottom: "10px",
          }}
        >
          <Title level={2} style={{...styles.sectionTitle, color: "#FFFFFF"}}>
            Your Collection
          </Title>
        </div>

        {/* Header section removed as requested */}

        <Row gutter={[16, 16]}>{content}</Row>
      </div>
    </div>
  );
};

// Wrap the component in React.memo to prevent unnecessary re-renders
export default React.memo(MyItemsSection);
