import { useReadContract, useWriteContract, useSimulateContract, useChainId } from 'wagmi';
import { parseEther } from 'viem';
import { G4M3_CONTRACT_CONFIG, G4M3_ABI, getContractAddressByChainId } from '../contracts/contracts';
import { useState, useEffect, useMemo } from 'react';
import { useWalletStatus, usePublicProvider } from './usePublicProvider';

/**
 * Custom hook to interact with the G4m3 NFT contract.
 * Provides access to read-only methods and contract state.
 */
export function useNFTContractRead() {
  // Check if we're in read-only mode
  const { isReadOnly } = useWalletStatus();
  const publicProvider = usePublicProvider();
  
  // Get the current chain ID to determine which contract to use
  const chainId = useChainId();
  
  // Get the correct contract address based on the chain ID
  const contractAddress = useMemo(() => {
    const address = getContractAddressByChainId(chainId);
    console.log(`Using contract address for chain ID ${chainId}:`, address);
    return address;
  }, [chainId]);
  
  // Create a dynamic contract config based on the current chain
  const contractConfig = useMemo(() => ({
    address: contractAddress,
    abi: G4M3_ABI,
  }), [contractAddress]);
  
  // Total supply of NFTs - always declare hooks regardless of isReadOnly
  const { data: totalSupply, isPending: isTotalSupplyLoading } = useReadContract({
    address: contractConfig.address,
    abi: contractConfig.abi,
    functionName: 'totalSupply',
    watch: true,
    enabled: !isReadOnly, // Only enable when not in read-only mode
  });

  // Check if minting is active - always declare hooks regardless of isReadOnly
  const { data: isMintingActive, isPending: isMintingActiveLoading, error: mintingActiveError } = useReadContract({
    address: contractConfig.address,
    abi: contractConfig.abi,
    functionName: 'isMintingActive',
    watch: true,
    enabled: !isReadOnly, // Only enable when not in read-only mode
  });
  
  // Debug logging - always declare hook but check condition inside
  useEffect(() => {
    if (!isReadOnly) {
      console.log("Contract Address:", contractConfig.address);
      console.log("isMintingActive:", isMintingActive);
      console.log("isMintingActiveLoading:", isMintingActiveLoading);
      if (mintingActiveError) {
        console.error("Error loading minting status:", mintingActiveError);
      }
    }
  }, [isMintingActive, isMintingActiveLoading, mintingActiveError, isReadOnly, contractConfig.address]);

  // Add a timeout for the loading state - always declare hooks
  const [timeoutMintingActive, setTimeoutMintingActive] = useState(false);
  
  // Always declare hooks, but conditionally execute logic inside
  useEffect(() => {
    if (!isReadOnly) {
      // If isMintingActive is still undefined after 10 seconds, set a default value
      const timer = setTimeout(() => {
        if (isMintingActive === undefined) {
          console.warn("Timed out waiting for isMintingActive, setting default value");
          setTimeoutMintingActive(true);
        }
      }, 10000);
      
      return () => clearTimeout(timer);
    }
  }, [isMintingActive, isReadOnly]);
  
  // For storing manually fetched data in read-only mode
  const [readOnlyData, setReadOnlyData] = useState({
    totalSupply: null,
    isMintingActive: null,
    isLoading: true
  });
  
  // In read-only mode, fetch the data directly using the public provider
  useEffect(() => {
    if (isReadOnly) {
      const fetchReadOnlyData = async () => {
        try {
          const totalSupplyResult = await publicProvider.readContract({
            address: contractConfig.address,
            abi: contractConfig.abi,
            functionName: 'totalSupply'
          });
          
          const isMintingActiveResult = await publicProvider.readContract({
            address: contractConfig.address,
            abi: contractConfig.abi,
            functionName: 'isMintingActive'
          });
          
          setReadOnlyData({
            totalSupply: totalSupplyResult,
            isMintingActive: isMintingActiveResult,
            isLoading: false
          });
        } catch (error) {
          console.error("Error fetching read-only data:", error);
          setReadOnlyData(prev => ({
            ...prev,
            isLoading: false
          }));
        }
      };
      
      fetchReadOnlyData();
    }
  }, [isReadOnly, publicProvider, contractConfig]);

  // Return the appropriate data based on read-only mode
  if (isReadOnly) {
    return {
      totalSupply: readOnlyData.totalSupply ? Number(readOnlyData.totalSupply) : null,
      isTotalSupplyLoading: readOnlyData.isLoading,
      isMintingActive: readOnlyData.isMintingActive,
      isMintingActiveLoading: readOnlyData.isLoading,
    };
  } else {
    return {
      totalSupply: totalSupply ? Number(totalSupply) : null,
      isTotalSupplyLoading,
      // If we've timed out, assume minting is inactive to avoid endless loading
      isMintingActive: timeoutMintingActive ? false : isMintingActive,
      isMintingActiveLoading: timeoutMintingActive ? false : isMintingActiveLoading,
    };
  }
}

/**
 * Hook for handling user-specific NFT contract reads
 */
export function useUserNFTInfo(address) {
  // Skip these calls if no address is available
  const enabled = !!address;
  
  // Get the current chain ID to determine which contract to use
  const chainId = useChainId();
  
  // Get the correct contract address based on the chain ID
  const contractAddress = useMemo(() => {
    return getContractAddressByChainId(chainId);
  }, [chainId]);
  
  // Create a dynamic contract config based on the current chain
  const contractConfig = useMemo(() => ({
    address: contractAddress,
    abi: G4M3_ABI,
  }), [contractAddress]);

  // User's NFT balance
  const { data: balance, isPending: isBalanceLoading } = useReadContract({
    address: contractConfig.address,
    abi: contractConfig.abi,
    functionName: 'balanceOf',
    args: [address || '0x0000000000000000000000000000000000000000'],
    enabled,
    watch: true,
  });

  // Check if user is eligible for free mint
  const { data: isFreeMintEligible, isPending: isFreeMintEligibleLoading } = useReadContract({
    address: contractConfig.address,
    abi: contractConfig.abi,
    functionName: 'isEligibleForFreeMint',
    args: [address || '0x0000000000000000000000000000000000000000'],
    enabled,
    watch: true,
  });

  // Get number of free mints remaining
  const { data: freeMintsRemaining, isPending: freeMintsRemainingLoading } = useReadContract({
    address: contractConfig.address,
    abi: contractConfig.abi,
    functionName: 'freeMintsRemaining',
    args: [address || '0x0000000000000000000000000000000000000000'],
    enabled,
    watch: true,
  });

  return {
    balance: balance ? Number(balance) : 0, 
    isBalanceLoading,
    isFreeMintEligible: isFreeMintEligible ?? false,
    isFreeMintEligibleLoading,
    freeMintsRemaining: freeMintsRemaining ? Number(freeMintsRemaining) : 0,
    freeMintsRemainingLoading,
  };
}

/**
 * Hook for minting NFTs
 */
export function useNFTMint() {
  // Get the current chain ID to determine which contract to use
  const chainId = useChainId();
  
  // Get the correct contract address based on the chain ID
  const contractAddress = useMemo(() => {
    return getContractAddressByChainId(chainId);
  }, [chainId]);
  
  // Create a dynamic contract config based on the current chain
  const contractConfig = useMemo(() => ({
    address: contractAddress,
    abi: G4M3_ABI,
  }), [contractAddress]);

  // Regular mint (0.02 ETH)
  const useMintItem = (address) => {
    const { data: config, error: prepareError } = useSimulateContract({
      address: contractConfig.address,
      abi: contractConfig.abi,
      functionName: 'mintItem',
      args: [address || '0x0000000000000000000000000000000000000000'],
      value: parseEther('0.02'),
      enabled: !!address,
    });

    const { writeContract: mintItemFn, isPending: isLoading, isSuccess, isError, error } = useWriteContract();

    const mintItem = () => {
      if (config) {
        mintItemFn(config.request);
      }
    };

    return {
      mintItem,
      isMintItemLoading: isLoading,
      isMintItemSuccess: isSuccess,
      isMintItemError: isError,
      mintItemError: error || prepareError,
    };
  };

  // Mint pack (4 tokens for 0.04 ETH)
  const useMintPack = (address) => {
    const { data: config, error: prepareError } = useSimulateContract({
      address: contractConfig.address,
      abi: contractConfig.abi,
      functionName: 'mintPack',
      args: [address || '0x0000000000000000000000000000000000000000'],
      value: parseEther('0.04'),
      enabled: !!address,
    });

    const { writeContract: mintPackFn, isPending: isLoading, isSuccess, isError, error } = useWriteContract();

    const mintPack = () => {
      if (config) {
        mintPackFn(config.request);
      }
    };

    return {
      mintPack,
      isMintPackLoading: isLoading,
      isMintPackSuccess: isSuccess,
      isMintPackError: isError,
      mintPackError: error || prepareError,
    };
  };

  // Free gated mint
  const useMintFreeGated = (noTokens) => {
    const { data: config, error: prepareError } = useSimulateContract({
      address: contractConfig.address,
      abi: contractConfig.abi,
      functionName: 'mintFreeGated',
      args: [noTokens],
      enabled: noTokens > 0,
    });

    const { writeContract: mintFreeGatedFn, isPending: isLoading, isSuccess, isError, error } = useWriteContract();

    const mintFreeGated = () => {
      if (config) {
        mintFreeGatedFn(config.request);
      }
    };

    return {
      mintFreeGated,
      isMintFreeGatedLoading: isLoading,
      isMintFreeGatedSuccess: isSuccess,
      isMintFreeGatedError: isError,
      mintFreeGatedError: error || prepareError,
    };
  };

  return {
    useMintItem,
    useMintPack,
    useMintFreeGated,
  };
}

