import React, { useState, useRef } from 'react';
import { ConnectButton } from '@rainbow-me/rainbowkit';

const Win95ConnectButton = ({ textStyle = false, displayBalance = true }) => {
  const [connectionError, setConnectionError] = useState(false);
  // Track which errors we've already shown to avoid duplicate messages
  const processedErrors = useRef({});
  
  // Simple function to show error message and hide it after 5 seconds
  const showError = (errorKey) => {
    // Only show each unique error once
    if (processedErrors.current[errorKey]) return;
    
    // Mark this error as processed
    processedErrors.current[errorKey] = true;
    
    console.error("Connection error detected:", errorKey);
    setConnectionError(true);
    setTimeout(() => setConnectionError(false), 5000);
  };

  return (
    <ConnectButton.Custom>
      {({
        account,
        chain,
        openAccountModal,
        openChainModal,
        openConnectModal,
        authenticationStatus,
        mounted,
        error,
      }) => {
        // Handle error display - setTimeout defers execution until after render
        if (error) {
          // Generate a unique error key based on the error message or object
          const errorKey = error.message || JSON.stringify(error) || String(Date.now());
          
          // Use setTimeout to defer the state update until after render
          setTimeout(() => showError(errorKey), 0);
        }

        // Note: If your app doesn't use authentication, you
        // can remove all 'authenticationStatus' checks
        const ready = mounted && authenticationStatus !== 'loading';
        const connected =
          ready &&
          account &&
          chain &&
          (!authenticationStatus ||
            authenticationStatus === 'authenticated');

        return (
          <div
            {...(!ready && {
              'aria-hidden': true,
              'style': {
                opacity: 0,
                pointerEvents: 'none',
                userSelect: 'none',
              },
            })}
          >
            {(() => {
              if (!connected) {
                return (
                  <>
                    {textStyle ? (
                      // Text-style connect button
                      <div 
                        onClick={() => {
                          setConnectionError(false);
                          openConnectModal();
                        }}
                        style={{
                          fontFamily: 'PixelOperator, monospace',
                          fontSize: '14px',
                          color: '#0070e0',
                          textDecoration: 'underline',
                          cursor: 'pointer',
                          textAlign: 'center',
                          padding: '5px 0',
                          userSelect: 'none'
                        }}
                      >
                        connect wallet
                      </div>
                    ) : (
                      // Regular button style
                      <button 
                        onClick={() => {
                          // Reset any previous error state
                          setConnectionError(false);
                          openConnectModal();
                        }} 
                        type="button"
                        className="win-button"
                        style={{
                          fontFamily: 'PixelOperator, monospace',
                          fontSize: '18px',
                          padding: '10px 20px'
                        }}
                      >
                        Connect Wallet
                      </button>
                    )}
                    
                    {connectionError && (
                      <div style={{ 
                        color: 'red', 
                        marginTop: '10px', 
                        fontFamily: 'PixelOperator, monospace',
                        border: '2px solid #ff0000',
                        backgroundColor: '#fff',
                        padding: '5px',
                        maxWidth: '250px'
                      }}>
                        Connection failed. Please try again or use a different wallet.
                      </div>
                    )}
                  </>
                );
              }

              if (chain.unsupported) {
                return textStyle ? (
                  // Text-style wrong network
                  <div
                    onClick={openChainModal}
                    style={{
                      fontFamily: 'PixelOperator, monospace',
                      fontSize: '14px',
                      color: '#ff0000',
                      textDecoration: 'underline',
                      cursor: 'pointer',
                      textAlign: 'center'
                    }}
                  >
                    wrong network (click to change)
                  </div>
                ) : (
                  // Regular button style for wrong network
                  <button 
                    onClick={openChainModal} 
                    type="button"
                    className="win-button"
                    style={{
                      fontFamily: 'PixelOperator, monospace',
                      backgroundColor: '#ff0000',
                      color: 'white',
                      borderColor: '#800000 #ffffff #ffffff #800000'
                    }}
                  >
                    Wrong network
                  </button>
                );
              }

              return textStyle ? (
                // Text-style connected state
                <div style={{ 
                  display: 'flex', 
                  justifyContent: 'center',
                  fontFamily: 'PixelOperator, monospace',
                  fontSize: '14px',
                  textAlign: 'center',
                  gap: '4px'
                }}>
                  {/* Account info */}
                  <div
                    onClick={openAccountModal}
                    style={{
                      color: '#0070e0',
                      textDecoration: 'underline',
                      cursor: 'pointer',
                    }}
                  >
                    connected wallet: {account.displayName}
                    {displayBalance && account.displayBalance
                      ? ` (${account.displayBalance})`
                      : ''}
                  </div>
                  
                  {/* Network info */}
                  <div style={{ color: '#000000' }}>
                    on{' '}
                    <span
                      onClick={openChainModal}
                      style={{
                        color: '#0070e0',
                        textDecoration: 'underline',
                        cursor: 'pointer'
                      }}
                    >
                      {chain.name}
                    </span>
                  </div>
                </div>
              ) : (
                // Regular button style connected state
                <div style={{ display: 'flex', gap: 12 }}>
                  <button
                    onClick={openChainModal}
                    className="win-button"
                    style={{ display: 'flex', alignItems: 'center' }}
                    type="button"
                  >
                    {chain.hasIcon && (
                      <div
                        style={{
                          background: chain.iconBackground,
                          width: 16,
                          height: 16,
                          borderRadius: 999,
                          overflow: 'hidden',
                          marginRight: 4,
                        }}
                      >
                        {chain.iconUrl && (
                          <img
                            alt={chain.name ?? 'Chain icon'}
                            src={chain.iconUrl}
                            style={{ width: 16, height: 16 }}
                          />
                        )}
                      </div>
                    )}
                    {chain.name}
                  </button>

                  <button 
                    onClick={openAccountModal} 
                    type="button"
                    className="win-button"
                  >
                    {account.displayName}
                    {displayBalance && account.displayBalance
                      ? ` (${account.displayBalance})`
                      : ''}
                  </button>
                </div>
              );
            })()}
          </div>
        );
      }}
    </ConnectButton.Custom>
  );
};

export default Win95ConnectButton;