// Determine which network to use based on deployment status
export const getTargetNetwork = () => {
  // Check environment variables first - they have highest priority
  if (
    process.env.REACT_APP_TARGET_NETWORK === "mainnet" ||
    process.env.REACT_APP_NETWORK === "mainnet"
  ) {
    console.log("📡 Using Ethereum Mainnet from environment variables");
    return NETWORKS.mainnet;
  }

  // Auto-detect GitHub Pages deployment
  const isGitHubPages = window.location.hostname.includes("github.io");

  // For production deployment (GitHub Pages)
  if (isGitHubPages) {
    console.log("📡 Using Ethereum Mainnet for production deployment");
    return NETWORKS.mainnet;
  }

  // For all local development (including https localhost), use localhost network
  console.log("🏠 Using local network for development");
  return NETWORKS.localhost;
};
