import React, { useState, useEffect, useRef } from 'react';
import { Card, Spin } from 'antd';

/**
 * ItemCard component for displaying NFTs in a Windows 3.11 style flippable card
 */
const ItemCard = ({ 
  item, 
  size = 'default', // 'default', 'small', 'gallery'
  onClick = null,
}) => {
  const [isFront, setIsFront] = useState(true);
  const [imageLoaded, setImageLoaded] = useState(false);
  const [isVisible, setIsVisible] = useState(false);
  const cardRef = useRef();

  // Function to flip card
  const flipCard = (e) => {
    // Prevent event bubbling
    if (e) e.stopPropagation();
    setIsFront(!isFront);
  };

  // Image load handler
  const handleImageLoad = () => {
    setImageLoaded(true);
  };

  // Setup intersection observer for lazy loading
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setIsVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.1 }, // Trigger when 10% of the element is visible
    );

    if (cardRef.current) {
      observer.observe(cardRef.current);
    }

    return () => {
      if (cardRef.current) {
        observer.unobserve(cardRef.current);
      }
    };
  }, []);
  
  // Render metadata content for card back
  const renderMetadata = () => (
    <div style={{ 
      width: "100%", 
      height: "100%", 
      display: "flex", 
      flexDirection: "column",
      padding: "10px", 
      backgroundColor: "#C0C0C0", // Windows 3.11 background color
      color: "#333", // Dark text color for readability
      fontFamily: "'PixelOperator', monospace", // Apply pixel font to the entire card back
      overflow: "auto" // Make content scrollable
    }}>
      <div style={{ 
        fontWeight: "bold", 
        fontSize: "1.1em", 
        marginBottom: "8px",
        textAlign: "center",
        background: "#000080", // Windows 3.11 title bar blue
        color: "#FFFFFF",
        padding: "3px 0",
        border: "1px solid #000000"
      }}>
        {item.name || `Token #${item.id}`}
      </div>
      
      <div style={{ 
        fontSize: "0.8em",
        marginBottom: "8px",
        padding: "4px",
        textAlign: "center",
        background: "#FFFFFF",
        border: "1px solid",
        borderColor: "#808080 #FFFFFF #FFFFFF #808080" // Windows 3.11 inset border
      }}>
        owned by: {item.owner && item.owner.startsWith("0x") ? 
          `${item.owner.substring(0, 10)}...${item.owner.substring(item.owner.length - 8)}` : 
          item.owner || 'Unknown'}
      </div>
      
      <div style={{ 
        marginTop: "8px", 
        fontSize: "1em",
        fontWeight: "bold",
        borderBottom: "1px solid #808080", 
        paddingBottom: "4px"
      }}>
        Traits:
      </div>
      
      <div style={{ overflow: "auto", flex: 1, marginTop: "4px" }}>
        {item.attributes && item.attributes.length > 0 ?
          item.attributes.map((a, iax) => (
            <div key={`attribute-${iax}`} style={{ 
              fontSize: "0.9em", 
              margin: "4px 0",
              display: "flex",
              justifyContent: "space-between",
              padding: "3px 5px",
              backgroundColor: "#C0C0C0"
            }}>
              <span style={{ fontWeight: "500" }}>{a.trait_type}:</span> 
              <span style={{ 
                background: "#FFFFFF", 
                border: "1px solid", 
                borderColor: "#808080 #FFFFFF #FFFFFF #808080", // Windows 3.11 inset border
                padding: "0 4px",
                minWidth: "60px",
                textAlign: "center"
              }}>{a.value}</span>
            </div>
          )) : (
            <div style={{ textAlign: "center", padding: "10px", color: "#666" }}>
              No traits available
            </div>
          )
        }
        
        {/* Additional info section */}
        <div style={{ 
          marginTop: "15px", 
          fontSize: "0.9em",
          borderTop: "1px solid #808080", 
          paddingTop: "8px"
        }}>
          <div style={{ fontWeight: "bold", marginBottom: "5px" }}>
            ID: <span style={{ fontWeight: "normal" }}>#{item.id}</span>
          </div>
          {item.description && (
            <div style={{ marginTop: "5px" }}>
              <div style={{ fontWeight: "bold", marginBottom: "2px" }}>Description:</div>
              <div style={{ 
                padding: "3px", 
                background: "#FFFFFF",
                border: "1px solid",
                borderColor: "#808080 #FFFFFF #FFFFFF #808080",
                minHeight: "35px",
                fontSize: "0.85em"
              }}>
                {item.description}
              </div>
            </div>
          )}
        </div>
      </div>
      
    </div>
  );

  // Gallery size is just the image without details and no flipping
  if (size === 'gallery' || size === 'small') {
    return (
      <Card
        hoverable
        style={{ 
          overflow: 'hidden',
          height: '150px',
          width: '150px',
          margin: '0', // Removed margin for snugger fit
          borderRadius: '0',
          border: '1px solid', // Reduced border width for snugger fit
          borderColor: '#ffffff #404040 #404040 #ffffff', // Windows 3.11 outset border
          padding: '0px',
          boxShadow: '1px 1px 0 rgba(0,0,0,0.1)' // Reduced shadow for snugger fit
        }}
        styles={{ body: { padding: '4px' } }} // Reduced padding for snugger fit
        onClick={onClick}
      >
        <div style={{
          position: 'relative',
          background: '#000',
          overflow: 'hidden',
          height: '100%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}>
          {item.image ? (
            <img 
              src={item.image} 
              alt={item.name || `Token #${item.id}`} 
              style={{ width: '100%', height: '100%', objectFit: 'cover' }}
            />
          ) : (
            <div style={{ color: '#fff', fontFamily: "'PixelOperator', monospace" }}>
              #{item.id}
            </div>
          )}
        </div>
      </Card>
    );
  }

  // Default size - flippable Windows 3.11 card
  return (
    <div 
      ref={cardRef} 
      style={{
        aspectRatio: "1/1", // Force 1:1 aspect ratio
        width: "100%",
        position: "relative",
        minHeight: "250px" // Minimum height for consistency
      }}
    >
      {/* Card container with flip animation */}
      <div 
        className={`card-container ${!isFront ? 'card-flipped' : ''}`} 
        onClick={flipCard}
        style={{
          perspective: "1000px",
          width: "100%",
          height: "100%",
          position: "relative",
          cursor: "pointer"
        }}
      >
        {/* Front of card (SVG) */}
        <div 
          className="card-front"
          style={{
            WebkitBackfaceVisibility: "hidden",
            backfaceVisibility: "hidden",
            transition: "transform 0.6s",
            WebkitTransitionProperty: "transform",
            WebkitTransitionDuration: "0.6s",
            transformStyle: "preserve-3d",
            WebkitTransformStyle: "preserve-3d",
            position: "absolute",
            top: "0",
            left: "0",
            width: "100%",
            height: "100%",
            borderRadius: "0",
            overflow: "hidden",
            boxShadow: "0 4px 8px rgba(0,0,0,0.1)",
            zIndex: "2",
            transform: isFront ? "rotateY(0deg)" : "rotateY(180deg)",
            WebkitTransform: isFront ? "rotateY(0deg)" : "rotateY(180deg)"
          }}
        >
          <Card
            style={{
              margin: "0",
              borderRadius: "0",
              border: "2px solid",
              borderColor: "#ffffff #404040 #404040 #ffffff", // Windows 3.11 outset border
              overflow: "hidden",
              backgroundColor: "white",
              padding: "0px",
              height: "100%",
              width: "100%",
              cursor: "pointer",
              boxShadow: "2px 2px 0 rgba(0,0,0,0.2)" // Windows 3.11 shadow
            }}
            styles={{ body: { padding: "0", height: "100%" } }}
          >
            {!isVisible ? (
              <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "100%" }}>
                {/* Placeholder for not yet visible */}
              </div>
            ) : !imageLoaded ? (
              <div style={{ display: "flex", justifyContent: "center", alignItems: "center", height: "100%" }}>
                <Spin tip="Loading..." />
              </div>
            ) : null}

            {isVisible && (
              <div style={{
                width: "100%",
                height: "100%",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                overflow: "hidden",
              }}>
                <img
                  src={item.image}
                  alt={item.name || `Token #${item.id}`}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    display: imageLoaded ? "block" : "none",
                  }}
                  onLoad={handleImageLoad}
                />
              </div>
            )}
          </Card>
        </div>
        
        {/* Back of card (Metadata) */}
        <div 
          className="card-back"
          style={{
            WebkitBackfaceVisibility: "hidden",
            backfaceVisibility: "hidden",
            transition: "transform 0.6s",
            WebkitTransitionProperty: "transform",
            WebkitTransitionDuration: "0.6s",
            transformStyle: "preserve-3d",
            WebkitTransformStyle: "preserve-3d",
            position: "absolute",
            top: "0",
            left: "0",
            width: "100%",
            height: "100%",
            borderRadius: "0",
            overflow: "hidden",
            boxShadow: "0 4px 8px rgba(0,0,0,0.1)",
            transform: isFront ? "rotateY(-180deg)" : "rotateY(0deg)",
            WebkitTransform: isFront ? "rotateY(-180deg)" : "rotateY(0deg)",
            zIndex: isFront ? "1" : "3",
            background: "#C0C0C0"
          }}
        >
          <Card
            style={{ 
              margin: "0", 
              borderRadius: "0", 
              border: "2px solid",
              borderColor: "#ffffff #404040 #404040 #ffffff", // Windows 3.11 outset border
              overflow: "auto",
              height: "100%",
              width: "100%",
              backgroundColor: "#C0C0C0",
              cursor: "pointer",
              boxShadow: "2px 2px 0 rgba(0,0,0,0.2)" // Windows 3.11 shadow
            }}
            styles={{ 
              body: { 
                padding: "0", 
                height: "100%",
                overflow: "auto",
                background: "#C0C0C0"
              }
            }}
          >
            {renderMetadata()}
          </Card>
        </div>
      </div>
    </div>
  );
};

export default ItemCard;