import React, { useEffect, useState, useRef, useMemo } from 'react';
import { Modal, Row, Col, Typography, Button, Progress } from 'antd';
import { PlayCircleOutlined, PauseCircleOutlined, StepForwardOutlined, StepBackwardOutlined } from '@ant-design/icons';
import ItemCard from './ItemCard';
import Win95Slider from './Win95Slider';

const { Text } = Typography;

/**
 * Modal for displaying animations of NFTs across generations
 */
const AnimationModal = ({ 
  visible, 
  onClose, 
  initialEpoch,
  tokens = [] 
}) => {
  // Animation control states
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentGeneration, setCurrentGeneration] = useState(0);
  const [speed, setSpeed] = useState(1000); // milliseconds between frames
  const [showDetails, setShowDetails] = useState(true);

  // Selected epoch
  const selectedEpoch = initialEpoch;

  // Refs for animation and token organization
  const animationRef = useRef(null);
  const tokensByGeneration = useRef({});
  const maxGeneration = useRef(0);

  // Reset state when modal opens or closes
  useEffect(() => {
    if (visible) {
      setIsPlaying(false);
      // Don't reset generation to 0 here - it will be set when validGenerations is available
    } else {
      // Stop animation when modal closes
      if (animationRef.current) {
        clearInterval(animationRef.current);
        animationRef.current = null;
      }
    }
  }, [visible]);

  // Group tokens by generation
  useEffect(() => {
    if (!tokens || tokens.length === 0) return;

    const genMap = {};
    let globalMaxGen = 0;

    console.log("Processing tokens for animation:", tokens.length);

    tokens.forEach(item => {
      if (!item.attributes) return;

      // Find generation attribute (account for both "generation" and "Generation" casing)
      const genAttr = item.attributes.find(attr => 
        attr.trait_type && attr.trait_type.toLowerCase() === "generation"
      );

      if (genAttr) {
        // Clean up the generation value (remove # if present and convert to number)
        const genValueStr = genAttr.value.toString().replace('#', '');
        const generation = parseInt(genValueStr, 10) || 0;

        console.log(`Processing token #${item.id} - Generation: ${generation}`, item);

        // Track max generation
        if (generation > globalMaxGen) {
          globalMaxGen = generation;
        }

        // Add token to generation
        if (!genMap[generation]) {
          genMap[generation] = [];
        }

        genMap[generation].push(item);
      } else {
        console.log(`Token #${item.id} has no generation attribute:`, item.attributes);
      }
    });

    const genCount = Object.keys(genMap).length;
    console.log(`Grouped ${tokens.length} tokens into ${genCount} generations. Max generation: ${globalMaxGen}`);
    
    // Print all generations and their token counts
    Object.keys(genMap).forEach(gen => {
      console.log(`Generation ${gen}: ${genMap[gen].length} tokens`);
    });

    tokensByGeneration.current = genMap;
    maxGeneration.current = globalMaxGen;

    // Initialize currentGeneration to the lowest available generation
    if (genCount > 0) {
      const minGen = Math.min(...Object.keys(genMap).map(g => parseInt(g)));
      setCurrentGeneration(minGen);
    }
  }, [tokens]);

  // Get valid generations
  const validGenerations = useMemo(() => {
    const generations = Object.keys(tokensByGeneration.current)
      .map(g => parseInt(g))
      .filter(g => !isNaN(g)) // Ensure only valid numbers
      .sort((a, b) => a - b);
    
    console.log("Valid generations for animation:", generations);
    return generations;
  }, [tokens, tokensByGeneration.current]);

  // Animation loop
  useEffect(() => {
    if (!isPlaying) return;

    // Clear any existing animation
    if (animationRef.current) {
      clearInterval(animationRef.current);
    }

    // Get the generations for this epoch
    const generations = Object.keys(tokensByGeneration.current).map(g => parseInt(g));

    if (generations.length === 0) {
      setIsPlaying(false);
      return;
    }

    const maxGen = Math.max(...generations);
    const minGen = Math.min(...generations);

    // Start animation loop
    animationRef.current = setInterval(() => {
      setCurrentGeneration(prev => {
        // Find next valid generation
        let nextGen = prev + 1;

        // Loop back to beginning if we exceed max
        if (nextGen > maxGen) {
          nextGen = minGen;
        }

        // Skip generations that don't have tokens
        while (!tokensByGeneration.current[nextGen] && nextGen <= maxGen) {
          nextGen++;
        }

        // If we went past the end, loop back to beginning
        if (nextGen > maxGen) {
          nextGen = minGen;
        }

        return nextGen;
      });
    }, speed);

    return () => {
      if (animationRef.current) {
        clearInterval(animationRef.current);
      }
    };
  }, [isPlaying, speed]);

  // Handle stepping through generations manually
  const handleStepForward = () => {
    const generations = Object.keys(tokensByGeneration.current).map(g => parseInt(g));

    if (generations.length === 0) return;

    const maxGen = Math.max(...generations);
    const minGen = Math.min(...generations);

    setCurrentGeneration(prev => {
      // Find next valid generation
      let nextGen = prev + 1;

      // Loop back to beginning if we exceed max
      if (nextGen > maxGen) {
        nextGen = minGen;
      }

      // Skip generations that don't have tokens
      while (!tokensByGeneration.current[nextGen] && nextGen <= maxGen) {
        nextGen++;
      }

      // If we went past the end, loop back to beginning
      if (nextGen > maxGen) {
        nextGen = minGen;
      }

      return nextGen;
    });
  };

  const handleStepBackward = () => {
    const generations = Object.keys(tokensByGeneration.current).map(g => parseInt(g));

    if (generations.length === 0) return;

    const maxGen = Math.max(...generations);
    const minGen = Math.min(...generations);

    setCurrentGeneration(prev => {
      // Find previous valid generation
      let prevGen = prev - 1;

      // Loop to end if we go below min
      if (prevGen < minGen) {
        prevGen = maxGen;
      }

      // Skip generations that don't have tokens
      while (!tokensByGeneration.current[prevGen] && prevGen >= minGen) {
        prevGen--;
      }

      // If we went past the beginning, loop to end
      if (prevGen < minGen) {
        prevGen = maxGen;
      }

      return prevGen;
    });
  };

  // Get current token to display
  const currentToken = useMemo(() => {
    if (validGenerations.length === 0) {
      // If no valid generations, try to show the first token from tokens array
      return tokens && tokens.length > 0 ? tokens[0] : null;
    }

    // Try to get tokens for the current generation
    const generationTokens = tokensByGeneration.current[currentGeneration] || [];

    if (generationTokens.length === 0) {
      // If this generation doesn't have tokens, try to find the first valid one
      for (const gen of validGenerations) {
        const tokensForGen = tokensByGeneration.current[gen] || [];
        if (tokensForGen.length > 0) {
          console.log(`Using token from generation ${gen} instead of ${currentGeneration}`);
          return tokensForGen[0];
        }
      }
      
      // Last resort - use first token from tokens array
      return tokens && tokens.length > 0 ? tokens[0] : null;
    }

    // Return the first token for this generation
    console.log(`Showing token from generation ${currentGeneration}:`, generationTokens[0]);
    return generationTokens[0];
  }, [currentGeneration, validGenerations, tokensByGeneration.current, tokens]);

  // Format token attributes for display
  const formatDetails = () => {
    if (!currentToken || !currentToken.attributes) return "No token selected";

    return (
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "8px" }}>
        {currentToken.attributes.map((attr, index) => (
          <span
            key={index}
            style={{
              background: "#FFFFFF",
              padding: "4px 8px",
              border: "2px solid",
              borderColor: "#404040 #FFFFFF #FFFFFF #404040",
              boxShadow: "1px 1px 0 #000000",
              fontSize: "12px",
              fontFamily: "'PixelOperator', monospace",
            }}
          >
            {attr.trait_type}: {attr.value}
          </span>
        ))}
      </div>
    );
  };

  // Custom styling for Win95/3.11 modal
  const modalCustomStyle = `
    /* Hide the default close button */
    .ant-modal-close {
      display: none !important;
    }
    
    /* Remove box shadow but keep transparent background */
    .ant-modal-content {
      box-shadow: none !important;
      background-color: transparent !important;
      padding: 0 !important;
    }
    
    /* Transparent body */
    .ant-modal-body {
      background-color: transparent !important;
      padding: 0 !important;
    }
  `;

  // Win95 button style
  const win95Button = {
    width: "30px",
    height: "30px",
    background: "#C0C0C0",
    color: "#000000",
    border: "2px solid",
    borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
    boxShadow: "1px 1px 0 #000000",
    padding: 0,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    cursor: "pointer",
    userSelect: "none",
    fontSize: "14px",
    fontWeight: "bold",
    fontFamily: "'PixelOperator', monospace",
  };

  if (!visible) return null;
  
  return (
    <>
      <style>{modalCustomStyle}</style>
      <Modal
        title={null} // Remove default title
        open={visible}
        onCancel={onClose}
        footer={null}
        closeIcon={null}
        width={900}
        style={{
          top: 20,
          maxWidth: "95vw",
          padding: 0,
          border: "none",
          backgroundColor: "#FFFFFF",
        }}
        bodyStyle={{
          padding: 0,
          margin: 0,
          maxHeight: "80vh",
          overflow: "visible", // Allow the custom title bar to be visible
          backgroundColor: "#FFFFFF",
          border: "none",
        }}
        centered
        maskStyle={{ backgroundColor: "rgba(0, 0, 0, 0.7)" }}
        wrapClassName="win95-modal-wrapper"
        modalRender={modal => (
          <div
            style={{
              background: "#FFFFFF",
              border: "2px solid",
              borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
              padding: 0,
              boxSizing: "border-box",
              overflow: "hidden",
              backgroundColor: "#FFFFFF",
              boxShadow: "1px 1px 0 #000000",
            }}
          >
            {/* Custom title bar */}
            <div
              style={{
                height: "22px",
                background: "#000080",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                padding: "0",
                borderBottom: "1px solid #000000",
                position: "relative",
                borderTop: "1px solid #FFFFFF",
                borderLeft: "1px solid #FFFFFF",
              }}
            >
              {/* Minimize button (just for styling, doesn't minimize) */}
              <div
                style={{
                  position: "absolute",
                  left: "2px",
                  top: "3px",
                  width: "16px",
                  height: "16px",
                  background: "#C0C0C0",
                  border: "2px solid",
                  borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                }}
                onClick={onClose}
              >
                <div
                  style={{
                    width: "8px",
                    height: "2px",
                    background: "#000000",
                    position: "absolute",
                  }}
                ></div>
              </div>

              <div
                style={{
                  color: "#FFFFFF",
                  fontSize: "12pt",
                  fontWeight: "normal",
                  fontFamily: "'04b_03', monospace",
                  letterSpacing: "1px",
                  textTransform: "uppercase",
                  paddingTop: "3px",
                  textAlign: "center",
                  flexGrow: 1,
                }}
              >
                g4m3 0f l1f3 Animation - Epoch {selectedEpoch || "?"}
              </div>

              {/* Close button */}
              <div
                style={{
                  position: "absolute",
                  right: "2px",
                  top: "3px",
                  width: "16px",
                  height: "16px",
                  background: "#C0C0C0",
                  border: "2px solid",
                  borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                }}
                onClick={onClose}
              >
                <div
                  style={{
                    position: "relative",
                    width: "8px",
                    height: "8px",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      width: "10px",
                      height: "2px",
                      background: "#000000",
                      top: "3px",
                      left: "-1px",
                      transform: "rotate(45deg)",
                    }}
                  ></div>
                  <div
                    style={{
                      position: "absolute",
                      width: "10px",
                      height: "2px",
                      background: "#000000",
                      top: "3px",
                      left: "-1px",
                      transform: "rotate(-45deg)",
                    }}
                  ></div>
                </div>
              </div>
            </div>

            {/* Content area */}
            <div
              style={{
                background: "#C0C0C0",
                margin: 0,
                padding: "12px",
                fontFamily: "'PixelOperator', monospace",
              }}
            >
              {modal}
            </div>
          </div>
        )}
      >
        {/* Vertical stacking of components */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "12px",
            background: "#C0C0C0",
            padding: "10px",
          }}
        >
          {/* 1. Top Section: Controls */}
          <div style={{ marginBottom: "8px" }}>
            <Row gutter={[16, 8]}>
              <Col xs={24} sm={12}>
                <div
                  style={{
                    fontSize: "12px",
                    fontWeight: "bold",
                    marginBottom: "6px",
                    borderBottom: "1px solid #000000",
                    paddingBottom: "2px",
                    color: "#000000",
                    textAlign: "left",
                    fontFamily: "'PixelOperator', monospace",
                  }}
                >
                  Animation Speed
                </div>

                <div style={{ display: "flex", alignItems: "center", marginBottom: "5px" }}>
                  <span
                    style={{
                      fontSize: "12px",
                      fontWeight: "bold",
                      marginRight: "4px",
                      color: "#000000",
                      minWidth: "30px",
                      fontFamily: "'PixelOperator', monospace",
                    }}
                  >
                    Slow
                  </span>

                  <div style={{ flex: 1 }}>
                    <Win95Slider
                      min={100}
                      max={2000}
                      step={100}
                      value={speed}
                      onChange={value => setSpeed(value)}
                      reverse
                    />
                  </div>

                  <span
                    style={{
                      fontSize: "12px",
                      fontWeight: "bold",
                      marginLeft: "4px",
                      color: "#000000",
                      minWidth: "30px",
                      textAlign: "right",
                      fontFamily: "'PixelOperator', monospace",
                    }}
                  >
                    Fast
                  </span>
                </div>
              </Col>

              <Col xs={24} sm={12}>
                <div
                  style={{
                    fontSize: "12px",
                    fontWeight: "bold",
                    marginBottom: "6px",
                    borderBottom: "1px solid #000000",
                    paddingBottom: "2px",
                    color: "#000000",
                    textAlign: "left",
                    fontFamily: "'PixelOperator', monospace",
                  }}
                >
                  Generation Control
                </div>

                <div style={{ display: "flex", alignItems: "center" }}>
                  <button
                    onClick={handleStepBackward}
                    disabled={validGenerations.length === 0}
                    style={{
                      ...win95Button,
                      opacity: validGenerations.length > 0 ? 1 : 0.5,
                      cursor: validGenerations.length > 0 ? "pointer" : "default",
                      fontFamily: "'PixelOperator', monospace",
                    }}
                  >
                    <StepBackwardOutlined />
                  </button>

                  <div style={{ flex: 1, margin: "0 8px" }}>
                    <Win95Slider
                      value={currentGeneration}
                      onChange={value => setCurrentGeneration(value)}
                      min={validGenerations.length > 0 ? Math.min(...validGenerations) : 0}
                      max={validGenerations.length > 0 ? Math.max(...validGenerations) : 0}
                      disabled={validGenerations.length === 0}
                    />
                  </div>

                  <button
                    onClick={handleStepForward}
                    disabled={validGenerations.length === 0}
                    style={{
                      ...win95Button,
                      opacity: validGenerations.length > 0 ? 1 : 0.5,
                      cursor: validGenerations.length > 0 ? "pointer" : "default",
                      fontFamily: "'PixelOperator', monospace",
                    }}
                  >
                    <StepForwardOutlined />
                  </button>
                </div>

                <div style={{ display: "flex", justifyContent: "center", marginTop: "8px" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
                    <span style={{ fontWeight: "bold", fontSize: "12px", fontFamily: "'PixelOperator', monospace" }}>
                      Show Details:
                    </span>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        cursor: "pointer",
                      }}
                      onClick={() => setShowDetails(!showDetails)}
                    >
                      <div
                        style={{
                          width: "14px",
                          height: "14px",
                          border: "2px solid",
                          borderColor: "#404040 #FFFFFF #FFFFFF #404040",
                          backgroundColor: "#FFFFFF",
                          position: "relative",
                          marginRight: "4px",
                          display: "flex",
                          justifyContent: "center",
                          alignItems: "center",
                        }}
                      >
                        {showDetails && (
                          <div
                            style={{
                              width: "8px",
                              height: "8px",
                              backgroundColor: "#000",
                            }}
                          />
                        )}
                      </div>
                      <div style={{ fontSize: "12px", fontFamily: "'PixelOperator', monospace" }}>
                        {showDetails ? "On" : "Off"}
                      </div>
                    </div>
                  </div>
                </div>
              </Col>

              <Col span={24} style={{ marginTop: "8px" }}>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                    gap: "8px",
                  }}
                >
                  <button
                    onClick={() => setIsPlaying(!isPlaying)}
                    disabled={validGenerations.length === 0}
                    style={{
                      width: "120px",
                      height: "32px",
                      background: "#C0C0C0",
                      color: "#000000",
                      fontSize: "12pt",
                      border: "2px solid",
                      borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                      boxShadow: "1px 1px 0 #000000",
                      padding: "0 10px",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      cursor: validGenerations.length > 0 ? "pointer" : "default",
                      opacity: validGenerations.length > 0 ? 1 : 0.5,
                      fontWeight: "bold",
                      fontFamily: "'PixelOperator', monospace",
                      userSelect: "none",
                    }}
                  >
                    {isPlaying ? (
                      <>
                        <PauseCircleOutlined style={{ marginRight: "6px" }} /> Stop
                      </>
                    ) : (
                      <>
                        <PlayCircleOutlined style={{ marginRight: "6px" }} /> Play
                      </>
                    )}
                  </button>
                </div>

                <div style={{ textAlign: "center", marginTop: "5px", fontSize: "12px", fontFamily: "'PixelOperator', monospace" }}>
                  Generation: {currentGeneration}
                </div>
              </Col>
            </Row>
          </div>

          {/* 2. Middle Section: Animation Container */}
          <div
            className="animation-container"
            style={{
              width: "100%",
              height: "350px",
              backgroundColor: "#000000",
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              overflow: "hidden",
              border: "2px solid",
              borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
              boxShadow: "1px 1px 0 #000000",
              marginBottom: "12px",
            }}
          >
            {currentToken ? (
              <img
                src={currentToken.image}
                alt={`Epoch ${selectedEpoch} Generation ${currentGeneration}`}
                style={{
                  maxWidth: "100%",
                  maxHeight: "100%",
                  objectFit: "contain",
                }}
              />
            ) : (
              <span
                style={{
                  color: "#666",
                  fontFamily: "'PixelOperator', monospace",
                  fontSize: "12px",
                  fontWeight: "bold",
                }}
              >
                {tokens.length > 0 ? "Select generation to view" : "No tokens found for this epoch"}
              </span>
            )}
          </div>

          {/* 3. Bottom Section: Details Panel (if shown) */}
          {showDetails && currentToken && (
            <div
              className="details-panel"
              style={{
                padding: "8px",
                backgroundColor: "#FFFFFF",
                color: "#000",
                border: "2px solid",
                borderColor: "#808080 #FFFFFF #FFFFFF #808080",
                boxShadow: "1px 1px 0 #000000",
                borderRadius: "0",
                maxHeight: "120px",
                overflow: "auto",
                marginTop: "0",
                fontFamily: "'PixelOperator', monospace",
              }}
            >
              <div
                style={{
                  borderBottom: "1px solid #000000",
                  paddingBottom: "2px",
                  marginBottom: "8px",
                }}
              >
                <div
                  style={{
                    color: "#000000",
                    fontSize: "12px",
                    fontWeight: "bold",
                    fontFamily: "'PixelOperator', monospace",
                    textAlign: "left",
                  }}
                >
                  Token #{currentToken?.id || "?"} Details
                </div>
              </div>

              <div
                style={{
                  backgroundColor: "#FFFFFF",
                  fontFamily: "'PixelOperator', monospace",
                  fontSize: "12px",
                  fontWeight: "bold",
                  textAlign: "center",
                }}
              >
                {formatDetails()}
              </div>
            </div>
          )}
        </div>
      </Modal>
    </>
  );
};

export default AnimationModal;