import React, { useState, useEffect } from "react";
import { Row, Col, Typography } from "antd";
import { useAccount, useChainId, useConfig } from "wagmi";
import { useNFTContractRead, useUserNFTInfo, useNFTMint } from "../../hooks";
import { Win95ConnectButton } from "../ui";
import { styles } from "./styles";
import { getContractAddressByChainId } from "../../contracts/contracts";

const { Title, Paragraph } = Typography;

const IntroSection = () => {
  const { address, isConnected, chainId: connectedChainId } = useAccount();
  const chainId = useChainId();
  const config = useConfig();
  const { isMintingActive } = useNFTContractRead();
  const { isFreeMintEligible, freeMintsRemaining } = useUserNFTInfo(address);
  const [noTokensForFreeMint, setNoTokensForFreeMint] = useState(0);

  // Setup mint functions from useNFTMint
  const { useMintItem, useMintPack, useMintFreeGated } = useNFTMint();
  const { mintItem } = useMintItem(address);
  const { mintPack } = useMintPack(address);
  const { mintFreeGated } = useMintFreeGated(noTokensForFreeMint);

  // Format the minting status for display
  const mintingStatusDisplay =
    isMintingActive !== undefined
      ? isMintingActive
        ? "Active"
        : "Inactive"
      : "Checking...";

  // Debug logging
  useEffect(() => {
    console.log("IntroSection isMintingActive:", isMintingActive);
  }, [isMintingActive]);

  // Get the network name based on the connected chain
  const getNetworkName = (chainId) => {
    if (chainId === 1) return "Ethereum Mainnet";
    if (chainId === 80002) return "Polygon Amoy Testnet";
    if (chainId === 31337) return "Localhost";
    return chainId ? `Chain ID: ${chainId}` : "Unknown Network";
  };

  // In wagmi v2, we can get the supported chains from config
  const supportedChains = config.chains.map((chain) => chain.id);

  // Check if the connected chain is supported
  const isNetworkMatch = supportedChains.includes(chainId);

  return (
    <div style={styles.section}>
      <div style={styles.container}>
        <Row justify="center" align="middle" gutter={[24, 40]}>
          <Col xs={24}>
            <div>
              <Title level={1} style={styles.sectionTitle}>
                g4m3 0f l1f3
              </Title>
              <Paragraph
                style={{
                  fontSize: "18px",
                  textAlign: "center",
                  maxWidth: "800px",
                  margin: "0 auto",
                  fontFamily: "'PixelOperator', monospace",
                }}
              >
                A collection of generative art based on Conway's cellular
                automaton. Starting from a rondom seed, each token evolves
                following automaton rules. An epoch ends once all cells perished
                or when patterns start repeating. Once this occures, a new epoch
                is seeded by the previous one. Until g4m3 0f l1f3 finally ends
                after 8 epochs. Each epoch ends according to the rules, or after
                256 generations have evolved.
              </Paragraph>

              <Paragraph
                style={{
                  fontSize: "14px",
                  textAlign: "center",
                  maxWidth: "800px",
                  margin: "10px auto 0",
                  fontFamily: "'PixelOperator', monospace",
                  opacity: 0.8,
                }}
              >
                Contract:{" "}
                {chainId
                  ? `${getContractAddressByChainId(
                      chainId
                    )} on ${getNetworkName(
                      chainId
                    )} | Minting: ${mintingStatusDisplay}`
                  : "Loading..."}
              </Paragraph>
            </div>
          </Col>
        </Row>

        {/* Mint Box */}
        <Row justify="center" style={{ marginTop: "40px" }}>
          <Col xs={24} md={18} lg={14}>
            <div style={styles.win95Window}>
              {/* Window Title Bar */}
              <div style={styles.win95TitleBar}>
                <div style={styles.win95TitleText}>Mint</div>
              </div>

              {/* Window Content */}
              <div style={styles.win95Content}>
                {/* Windows Textbox */}
                <div
                  style={{
                    padding: "12px",
                    marginBottom: "5px",
                    textAlign: "center",
                    color: "#000000",
                    fontSize: "12pt",
                    fontWeight: "600",
                    fontFamily: "'PixelOperator', monospace",
                    lineHeight: "1.3",
                  }}
                >
                  Mint the next generations and help g4m3 0f l1f3 unfold
                </div>

                {/* Text-style connect button centered under the text */}
                <div
                  style={{
                    marginBottom: "20px",
                    display: "flex",
                    justifyContent: "center",
                  }}
                >
                  <Win95ConnectButton textStyle={true} />
                </div>

                {isConnected ? (
                  <>
                    {/* Minting not active warning */}
                    {isMintingActive === false && (
                      <div
                        style={{
                          marginBottom: "12px",
                          padding: "8px",
                        }}
                      >
                        <div
                          style={{
                            color: "#000000",
                            fontWeight: "normal",
                            fontSize: "11pt",
                            fontFamily: "'04b_03', monospace",
                            background: "#FFFF00",
                            border: "1px solid #000000",
                            padding: "2px 0",
                            marginBottom: "8px",
                          }}
                        >
                          ⚠️ MINTING DISABLED ⚠️
                        </div>
                        <div
                          style={{
                            fontSize: "12pt",
                            color: "#000000",
                            fontWeight: "bold",
                            fontFamily: "'PixelOperator', monospace",
                            lineHeight: "1.3",
                            background: "#FFFFFF",
                            border: "1px solid",
                            borderColor: "#808080 #FFFFFF #FFFFFF #808080",
                            padding: "6px",
                          }}
                        >
                          Minting is currently disabled on the contract. Please
                          check back later.
                        </div>
                      </div>
                    )}

                    {/* Network mismatch warning */}
                    {!isNetworkMatch && chainId && (
                      <div
                        style={{
                          marginBottom: "12px",
                          padding: "8px",
                        }}
                      >
                        <div
                          style={{
                            color: "#000000",
                            fontWeight: "normal",
                            fontSize: "11pt",
                            fontFamily: "'04b_03', monospace",
                            background: "#FFFF00",
                            border: "1px solid #000000",
                            padding: "2px 0",
                            marginBottom: "8px",
                          }}
                        >
                          ⚠️ NETWORK MISMATCH ⚠️
                        </div>
                        <div
                          style={{
                            fontSize: "12pt",
                            color: "#000000",
                            fontWeight: "bold",
                            fontFamily: "'PixelOperator', monospace",
                            lineHeight: "1.3",
                            background: "#FFFFFF",
                            border: "1px solid",
                            borderColor: "#808080 #FFFFFF #FFFFFF #808080",
                            padding: "6px",
                          }}
                        >
                          Your wallet is connected to the wrong network (
                          {getNetworkName(chainId)}). Please switch to Ethereum
                          Mainnet or Polygon Amoy testnet. Minting is disabled
                          until networks match.
                        </div>
                      </div>
                    )}

                    {/* Free mint section */}
                    {isNetworkMatch &&
                      isMintingActive &&
                      isFreeMintEligible &&
                      freeMintsRemaining > 0 && (
                        <div style={{ marginBottom: "12px" }}>
                          <div
                            style={{
                              fontSize: "12pt",
                              color: "#000000",
                              marginBottom: "12px",
                              fontWeight: "bold",
                              fontFamily: "'PixelOperator', monospace",
                              padding: "6px",
                            }}
                          >
                            Free Mints Available: {freeMintsRemaining}
                          </div>

                          <div
                            style={{
                              display: "flex",
                              justifyContent: "center",
                              marginBottom: "10px",
                            }}
                          >
                            <div
                              style={{
                                display: "flex",
                                alignItems: "center",
                                padding: "0px",
                              }}
                            >
                              {/* Minus Button */}
                              <button
                                style={{
                                  height: "28px",
                                  width: "28px",
                                  display: "flex",
                                  alignItems: "center",
                                  justifyContent: "center",
                                  fontSize: "14pt",
                                  padding: 0,
                                  background: "#C0C0C0",
                                  color: "#000000",
                                  border: "2px solid",
                                  borderColor:
                                    "#FFFFFF #404040 #404040 #FFFFFF",
                                  boxShadow: "1px 1px 0 #000000",
                                  cursor: "pointer",
                                  fontWeight: "bold",
                                  fontFamily: "'PixelOperator', monospace",
                                  userSelect: "none",
                                }}
                                onClick={() => {
                                  const newValue = Math.max(
                                    0,
                                    noTokensForFreeMint - 1
                                  );
                                  setNoTokensForFreeMint(newValue);
                                }}
                              >
                                -
                              </button>

                              {/* Count Display */}
                              <div
                                style={{
                                  padding: "0 8px",
                                  fontSize: "12pt",
                                  fontWeight: "bold",
                                  fontFamily: "'PixelOperator', monospace",
                                  color: "#000000",
                                  minWidth: "35px",
                                  height: "28px",
                                  display: "flex",
                                  alignItems: "center",
                                  justifyContent: "center",
                                  textAlign: "center",
                                  background: "#FFFFFF",
                                  border: "2px solid",
                                  borderColor:
                                    "#808080 #FFFFFF #FFFFFF #808080",
                                  margin: "0 7px",
                                }}
                              >
                                {noTokensForFreeMint}
                              </div>

                              {/* Plus Button */}
                              <button
                                style={{
                                  height: "28px",
                                  width: "28px",
                                  display: "flex",
                                  alignItems: "center",
                                  justifyContent: "center",
                                  fontSize: "12pt",
                                  padding: 0,
                                  background: "#C0C0C0",
                                  color: "#000000",
                                  border: "2px solid",
                                  borderColor:
                                    "#FFFFFF #404040 #404040 #FFFFFF",
                                  boxShadow: "1px 1px 0 #000000",
                                  cursor: "pointer",
                                  fontWeight: "bold",
                                  fontFamily: "'PixelOperator', monospace",
                                  userSelect: "none",
                                }}
                                onClick={() => {
                                  const newValue = Math.min(
                                    freeMintsRemaining,
                                    noTokensForFreeMint + 1
                                  );
                                  setNoTokensForFreeMint(newValue);
                                }}
                              >
                                +
                              </button>
                            </div>
                          </div>

                          {/* Mint Free Button */}
                          <button
                            style={{
                              ...styles.win95Button,
                              ...(!isNetworkMatch ||
                              !isMintingActive ||
                              noTokensForFreeMint === 0
                                ? styles.win95ButtonDisabled
                                : {}),
                            }}
                            disabled={
                              !isNetworkMatch ||
                              !isMintingActive ||
                              noTokensForFreeMint === 0
                            }
                            onClick={() => {
                              if (
                                isNetworkMatch &&
                                isMintingActive &&
                                noTokensForFreeMint > 0
                              ) {
                                mintFreeGated?.();
                              }
                            }}
                          >
                            Mint <u>f</u>ree ({noTokensForFreeMint} of{" "}
                            {freeMintsRemaining})
                          </button>
                        </div>
                      )}

                    {/* Divider between free and paid mints */}
                    {isNetworkMatch &&
                      isMintingActive &&
                      isFreeMintEligible &&
                      freeMintsRemaining > 0 && (
                        <hr
                          style={{
                            height: "2px",
                            margin: "15px 0",
                            border: "none",
                            background: "#C0C0C0",
                            position: "relative",
                          }}
                        />
                      )}

                    {/* Paid mint buttons */}
                    <div
                      style={{
                        display: "flex",
                        flexWrap: "wrap",
                        justifyContent: "center",
                        gap: "15px",
                        marginBottom: "10px",
                      }}
                    >
                      {/* Mint One Button */}
                      <button
                        style={{
                          ...styles.win95Button,
                          ...(!isNetworkMatch || !isMintingActive
                            ? styles.win95ButtonDisabled
                            : {}),
                        }}
                        disabled={!isNetworkMatch || !isMintingActive}
                        onClick={() => {
                          if (isNetworkMatch && isMintingActive) {
                            mintItem?.();
                          }
                        }}
                      >
                        <u>M</u>int one (0.02 ETH)
                      </button>

                      {/* Mint Pack Button */}
                      <button
                        style={{
                          ...styles.win95Button,
                          minWidth: "200px",
                          ...(!isNetworkMatch || !isMintingActive
                            ? styles.win95ButtonDisabled
                            : {}),
                        }}
                        disabled={!isNetworkMatch || !isMintingActive}
                        onClick={() => {
                          if (isNetworkMatch && isMintingActive) {
                            mintPack?.();
                          }
                        }}
                      >
                        Mint <u>s</u>equence (4 tokens - 0.04 ETH)
                      </button>
                    </div>
                  </>
                ) : (
                  <div
                    style={{
                      fontSize: "12pt",
                      color: "#000000",
                      marginBottom: "12px",
                      fontWeight: "bold",
                      fontFamily: "'PixelOperator', monospace",
                      padding: "6px",
                    }}
                  >
                    Connect wallet to mint
                  </div>
                )}
              </div>
            </div>
          </Col>
        </Row>
      </div>
    </div>
  );
};

export default IntroSection;
