import { useReducer, useEffect, useCallback, useMemo, useRef } from 'react';
import { useUserNFTInfo } from './useNFTContract';
import { useAccount, useReadContracts, useChainId } from 'wagmi';
import { G4M3_CONTRACT_CONFIG, getContractAddressByChainId } from '../contracts/contracts';

// Define reducer initial state
const initialState = {
  status: 'idle', // 'idle', 'loading', 'success', 'error'
  yourCollectibles: [],
  collectiblesByEpoch: {},
  detectedCollectibles: 0,
  error: null,
  lastUpdated: null
};

// Reducer to manage all NFT collection state
function tokenReducer(state, action) {
  switch (action.type) {
    case 'FETCH_START':
      return { ...state, status: 'loading' };
    case 'FETCH_SUCCESS':
      return {
        ...state,
        status: 'success',
        yourCollectibles: action.payload.collectibles,
        collectiblesByEpoch: action.payload.byEpoch,
        detectedCollectibles: action.payload.detectedCount,
        lastUpdated: Date.now()
      };
    case 'FETCH_ERROR':
      return { 
        ...state, 
        status: 'error', 
        error: action.payload 
      };
    case 'RESET':
      return initialState;
    default:
      return state;
  }
}

/**
 * Simplified hook that manages the user's NFT collection with clear data flow
 */
export function useNFTCollection() {
  const { address, isConnected } = useAccount();
  const { balance, isBalanceLoading } = useUserNFTInfo(address);
  
  // Get the current chain ID for network-aware caching
  const chainId = useChainId();
  
  // Track if component is mounted
  const isMounted = useRef(true);
  
  // Use reducer instead of multiple state variables
  const [state, dispatch] = useReducer(tokenReducer, initialState);
  
  // Get contract address for the current network
  const contractAddress = getContractAddressByChainId(chainId);
  
  // Network-aware cache key for localStorage caching
  const cacheKey = useMemo(() => 
    `collectibles-${chainId}-${address || "none"}`,
    [chainId, address]
  );
  
  // Process token data (stable implementation)
  const processTokenData = useCallback((tokenIds, uriResponses, ownerAddress) => {
    if (!uriResponses || uriResponses.length === 0) return [];
    
    const collectibles = [];
    
    // Process each URI response
    uriResponses.forEach((response, index) => {
      const uri = response?.result;
      const id = tokenIds[index];
      
      if (uri) {
        try {
          // Parse the base64 encoded data
          const jsonManifestString = atob(uri.substring(29));
          const jsonManifest = JSON.parse(jsonManifestString);
          
          collectibles.push({
            id,
            uri,
            owner: ownerAddress,
            chainId,
            ...jsonManifest
          });
        } catch (error) {
          console.error(`Error parsing token ${id} manifest:`, error);
        }
      }
    });
    
    return collectibles;
  }, [chainId]);
  
  // Organize tokens by epoch - utility function
  const organizeByEpoch = useCallback((collectibles) => {
    const byEpoch = {};
    
    collectibles.forEach(token => {
      if (!token.attributes) return;
      
      // Find epoch attribute
      const epochAttr = token.attributes.find(attr => attr.trait_type === "epoch");
      if (epochAttr) {
        const epoch = epochAttr.value.replace("#", "");
        
        if (!byEpoch[epoch]) {
          byEpoch[epoch] = [];
        }
        
        byEpoch[epoch].push(token);
      }
    });
    
    // Sort tokens within each epoch by generation
    Object.keys(byEpoch).forEach(epoch => {
      byEpoch[epoch].sort((a, b) => {
        const getGeneration = item => {
          const genAttr = item.attributes?.find(attr => attr.trait_type === "generation");
          return genAttr ? parseInt(genAttr.value.replace("#", "")) : 0;
        };
        
        return getGeneration(a) - getGeneration(b);
      });
    });
    
    return byEpoch;
  }, []);
  
  // Create batch query configs for token IDs with network awareness
  const createTokenIdQueries = useCallback((address, balance) => {
    if (!address || balance === 0 || !contractAddress) return [];
    
    // Create batch of queries for all token indices
    return Array.from({ length: balance }, (_, i) => ({
      address: contractAddress,
      abi: G4M3_CONTRACT_CONFIG.abi,
      functionName: 'tokenOfOwnerByIndex',
      args: [address, i],
    }));
  }, [contractAddress]);
  
  // Create batch query configs for token URIs with network awareness
  const createTokenURIQueries = useCallback((tokenIds) => {
    if (!tokenIds || tokenIds.length === 0 || !contractAddress) return [];
    
    // Create batch of queries for all token IDs
    return tokenIds.map(id => ({
      address: contractAddress,
      abi: G4M3_CONTRACT_CONFIG.abi,
      functionName: 'tokenURI',
      args: [id],
    }));
  }, [contractAddress]);
  
  // Get token ID queries for the current user and balance
  const tokenIdQueries = useMemo(() => 
    createTokenIdQueries(address, balance),
    [createTokenIdQueries, address, balance]
  );
  
  // Use wagmi's batch read contract hook for token IDs
  const { 
    data: tokenIdResults,
    isPending: isTokenIdLoading,
    refetch: refetchTokenIds,
  } = useReadContracts({
    contracts: tokenIdQueries,
    query: {
      enabled: isConnected && balance > 0 && !!contractAddress,
    }
  });
  
  // Extract token IDs from results
  const tokenIds = useMemo(() => 
    tokenIdResults ? 
      tokenIdResults
        .map(result => result?.result ? Number(result.result) : null)
        .filter(id => id !== null) : 
      [],
    [tokenIdResults]
  );
  
  // Create token URI queries based on extracted token IDs
  const tokenURIQueries = useMemo(() => 
    createTokenURIQueries(tokenIds),
    [createTokenURIQueries, tokenIds]
  );
  
  // Use wagmi's batch read contract hook for URIs
  const {
    data: tokenURIResults,
    isPending: isTokenURILoading,
    refetch: refetchTokenURIs,
  } = useReadContracts({
    contracts: tokenURIQueries,
    query: {
      enabled: isConnected && tokenIds.length > 0 && !!contractAddress,
    }
  });
  
  // Main token processing function - core of the refactored hook
  const processAndUpdateTokens = useCallback((forceRefresh = false) => {
    // Skip if not connected
    if (!isConnected || !isMounted.current) {
      dispatch({ type: 'RESET' });
      return;
    }
    
    // Start loading
    dispatch({ type: 'FETCH_START' });
    
    try {
      // Check cache first unless force refresh
      if (!forceRefresh) {
        const cachedData = localStorage.getItem(cacheKey);
        if (cachedData) {
          try {
            const parsed = JSON.parse(cachedData);
            const { collection, byEpoch, timestamp } = parsed;
            
            // Check if cache is valid and matches current balance
            const CACHE_VALID_TIME = 5 * 60 * 1000; // 5 minutes
            const isCacheValid = (Date.now() - timestamp) < CACHE_VALID_TIME;
            
            if (isCacheValid && collection && collection.length === balance) {
              console.log(`Using cached collection with ${collection.length} items for chain ${chainId}`);
              
              if (isMounted.current) {
                dispatch({
                  type: 'FETCH_SUCCESS',
                  payload: {
                    collectibles: collection,
                    byEpoch: byEpoch || {},
                    detectedCount: collection.length
                  }
                });
                return; // Exit early with cached data
              }
            }
          } catch (err) {
            console.warn("Error parsing cached collectibles:", err);
          }
        }
      }
      
      // If we need fresh data, trigger refetch
      if (forceRefresh) {
        refetchTokenIds();
        if (tokenIds.length) {
          refetchTokenURIs();
        }
      }
      
      // Exit if no token IDs
      if (!tokenIds || tokenIds.length === 0) {
        if (!isTokenIdLoading) {
          dispatch({ 
            type: 'FETCH_SUCCESS', 
            payload: { 
              collectibles: [], 
              byEpoch: {},
              detectedCount: 0
            } 
          });
        }
        return;
      }
      
      // Skip if URI data is still loading
      if (!tokenURIResults || isTokenURILoading) {
        return;
      }
      
      // Process the results
      const collectibles = processTokenData(tokenIds, tokenURIResults, address);
      
      // Group by epoch for better display
      const byEpoch = organizeByEpoch(collectibles);
      
      // Update state with success
      if (isMounted.current) {
        dispatch({
          type: 'FETCH_SUCCESS',
          payload: {
            collectibles,
            byEpoch,
            detectedCount: tokenIds.length
          }
        });
      }
      
      // Cache the results
      const cacheData = {
        collection: collectibles,
        byEpoch,
        timestamp: Date.now(),
        chainId
      };
      
      localStorage.setItem(cacheKey, JSON.stringify(cacheData));
      
    } catch (error) {
      console.error('Error processing tokens:', error);
      if (isMounted.current) {
        dispatch({ type: 'FETCH_ERROR', payload: error.message });
      }
    }
  }, [
    isConnected, cacheKey, chainId, balance, address, tokenIds, tokenURIResults,
    isTokenIdLoading, isTokenURILoading, processTokenData, organizeByEpoch,
    refetchTokenIds, refetchTokenURIs
  ]);
  
  // Monitor changes in data and process tokens when needed
  useEffect(() => {
    // Initially set the mounted ref
    isMounted.current = true;
    
    // Reset state when disconnected
    if (!isConnected) {
      dispatch({ type: 'RESET' });
      return;
    }
    
    // Process tokens when data changes
    processAndUpdateTokens();
    
    // Cleanup
    return () => {
      isMounted.current = false;
    };
  }, [chainId, address, isConnected, tokenURIResults, tokenIds, processAndUpdateTokens]);
  
  // Derive loading state from reducer state and balance loading
  const isLoading = state.status === 'loading' || isBalanceLoading;
  
  // Return stable object with state and actions
  return useMemo(() => ({
    yourCollectibles: state.yourCollectibles,
    collectiblesByEpoch: state.collectiblesByEpoch,
    isLoading,
    detectedCollectibles: state.detectedCollectibles,
    balance,
    refetchTokens: () => processAndUpdateTokens(true)
  }), [
    state.yourCollectibles,
    state.collectiblesByEpoch,
    isLoading,
    state.detectedCollectibles,
    balance,
    processAndUpdateTokens
  ]);
}